local config = {
  ui_story_5063_50630101_1_dialog_content = "(Ai... Minha cabeça.)",
  ui_story_5063_50630101_2_dialog_content = "(Devo estar mais cansado do que pensei, para adormecer de repente assim ao ar livre.)",
  ui_story_5063_50630101_3_dialog_content = "(Graças a Deus acordei agora. Ainda devo ter tempo suficiente para a minha próxima reunião.)",
  ui_story_5063_50630101_4_dialog_content = "Aguarde, por favor!",
  ui_story_5063_50630101_5_dialog_content = "Hum?",
  ui_story_5063_50630101_6_dialog_content = "No momento, a Corte de Justiça está em sessão fechada. Indivíduos não autorizados não têm permissão para entrar.",
  ui_story_5063_50630101_7_dialog_content = "Vocês são guardas novos, por acaso?",
  ui_story_5063_50630101_8_dialog_content = "Acontece que sou o Juiz Chefe aqui no Tribunal de Justiça.",
  ui_story_5063_50630101_9_dialog_content = "Estou organizando uma reunião muito importante que começará em breve. Por favor, deixem-me passar para que eu possa começar os preparativos.",
  ui_story_5063_50630101_10_dialog_content = "Você está <color=#FFB400>vestido como um cavaleiro</color>, mas tem a audácia de se passar pela estimada Juíza Chefe neste sagrado local?",
  ui_story_5063_50630101_11_dialog_content = "Uma pessoa com intenções tão ardilosas - como podemos permitir que você engane dessa maneira?!",
  ui_story_5063_50630101_12_dialog_content = "Realmente admiro sua dedicação e sinceridade, mas eu realmente sou o Juiz Chefe de Lumopolis! Se você ainda não acredita em mim...",
  ui_story_5063_50630101_13_dialog_content = "Você não vai desistir disso, né? Parece que teremos que detê-lo para uma investigação minuciosa!",
  ui_story_5063_50630101_14_dialog_content = "O que você disse para mim?",
  ui_story_5063_50630101_15_dialog_content = "Pare aí mesmo!!!",
  ui_story_5063_50630102_1_dialog_content = "(Por que nenhum desses guardas me reconhece?)",
  ui_story_5063_50630102_2_dialog_content = "(Também... Quando foi que eu troquei para este uniforme de cavaleiro? Eu não me lembro de ter feito isso!)",
  ui_story_5063_50630102_3_dialog_content = "Pare! Não ouse correr!",
  ui_story_5063_50630102_4_dialog_content = "...",
  ui_story_5063_50630102_5_dialog_content = "Isso é ruim. Ela está prestes a invadir o Hall of Justice!",
  ui_story_5063_50630102_6_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5063_50630102_7_dialog_content = "Tão brilhante... O que é aquilo?",
  ui_story_5063_50630102_8_dialog_content = "Pedimos desculpas, Juiz Chefe!",
  ui_story_5063_50630102_9_dialog_content = "(Eles... finalmente me reconhecem?)",
  ui_story_5063_50630102_10_dialog_content = "Juiz Chefe, pedimos desculpas profundamente por assustá-lo! Nós vamos levar este impostor ardiloso sob custódia imediatamente!",
  ui_story_5063_50630102_11_dialog_content = "(Os guardas... Eles não parecem estar falando comigo.)",
  ui_story_5063_50630102_12_dialog_content = "Obrigado a todos pela ajuda.",
  ui_story_5063_50630102_13_dialog_content = "Esta aqui é uma nova Cavaleira da Justiça no Tribunal de Justiça, então provavelmente ela não está familiarizada com as regras daqui.",
  ui_story_5063_50630102_14_dialog_content = "Vou me certificar de orientá-la sobre como se comportar no Tribunal de Justiça. O restante de vocês pode ir embora por enquanto.",
  ui_story_5063_50630102_15_dialog_content = "Sim, Juiz Chefe!",
  ui_story_5063_50630102_16_dialog_content = "... <color=#FFB400>Juiz Chefe</color>?!",
  ui_story_5063_50630102_17_dialog_content = "Mas apenas uma pessoa pode ser Juiz Chefe... O que está acontecendo?!",
  ui_story_5063_50630102_18_dialog_content = "Entrada não autorizada no Salão da Justiça, você tem muita audácia.",
  ui_story_5063_50630102_19_dialog_content = "Peço desculpas? Eu sou Irridon, a Juíza Chefe da Corte de Justiça de Lumópolis, e tenho total liberdade para ir e vir como eu quiser...",
  ui_story_5063_50630102_20_dialog_content = "Agora me diga, o que você pensa que está fazendo no meu lugar?",
  ui_story_5063_50630102_21_dialog_content = "Ter sonhos é bom, mas você precisa avaliar cuidadosamente se tem habilidade para realizá-los.",
  ui_story_5063_50630102_22_dialog_content = "Sempre apreciei jovens com aspirações, mas não aqueles perdidos em devaneios.",
  ui_story_5063_50630102_23_dialog_content = "Tenha uma visão clara de onde você está. Se você deseja continuar servindo ao Tribunal de Justiça...",
  ui_story_5063_50630102_24_dialog_content = "A partir de agora, faça como eu digo e observe o que eu faço.",
  ui_story_5063_50630102_25_dialog_content = "\"Faça como eu digo e observe como eu faço...\" Mas essa é a <color=#FFB400>frase favorita do meu pai</color>! Como você sabe disso?!",
  ui_story_5063_50630102_26_dialog_content = "Sou o sucessor escolhido e favorecido por seu pai, o Juiz Chefe Rodell.",
  ui_story_5063_50630102_27_dialog_content = "Não pense que só porque seu pai é Juiz Chefe, você se tornará automaticamente Juiz Chefe algum dia.",
  ui_story_5063_50630102_28_dialog_content = "Neste momento, você é apenas um novo e comum Cavaleiro da Justiça no Tribunal de Justiça.",
  ui_story_5063_50630102_29_dialog_content = "Eu sou... apenas um Cavaleiro da Justiça?",
  ui_story_5063_50630102_30_dialog_content = "Parece que você realmente se perdeu em um devaneio; ainda não acordou?",
  ui_story_5063_50630102_31_dialog_content = "(Um sonho... É verdade, eu tive alguns sonhos estranhos esta manhã, mas não consigo me lembrar de nenhum deles agora.)",
  ui_story_5063_50630102_32_dialog_content = "(E-Eu estava sonhando o tempo todo? Por que eu pensei que era o Juiz Chefe agora há pouco?",
  ui_story_5063_50630102_33_dialog_content = "(Aqueles sonhos... Eles devem ter sido tão realistas que eu pensei que fossem verdade!)",
  ui_story_5063_50630102_34_dialog_content = "(Então meu comportamento com aqueles guardas agora há pouco... Aos olhos deles, eu não era diferente de um mentiroso!)",
  ui_story_5063_50630102_35_dialog_content = "Por favor, perdoe meu comportamento descortês, Juiz Chefe...",
  ui_story_5063_50630102_36_dialog_content = "Bem, sua atitude parece mesmo sincera.",
  ui_story_5063_50630102_37_dialog_content = "Por respeito ao seu pai, vou deixar passar dessa vez. Volte e reflita sobre suas atitudes; recompense-me através de suas ações.",
  ui_story_5063_50630102_38_dialog_content = "Agora, vá e cumpra suas responsabilidades agora.",
  ui_story_5063_50630102_39_dialog_content = "Obrigado, Juiz Chefe!",
  ui_story_5063_50630102_40_dialog_content = "(Não acredito que cometi um erro tão terrível logo no meu primeiro dia. Que vergonha.)",
  ui_story_5063_50630102_41_dialog_content = "(Graças a Deus o Juiz Chefe teve a gentileza de ignorar minha transgressão...)",
  ui_story_5063_50630102_42_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5063_50630102_43_dialog_content = "Onde está a Juíza Chefe?!",
  ui_story_5063_50630102_44_dialog_content = "Juiz Chefe!",
  ui_story_5063_50630102_45_dialog_content = "Acredito que você esteja enganado. A Juíza Chefe está sentada ali.",
  ui_story_5063_50630102_46_dialog_content = "Identifique-se.",
  ui_story_5063_50630102_47_dialog_content = "Juiz Chefe, minha família e eu fomos injustamente acusados, e esperamos que você possa nos ajudar a buscar justiça e limpar nossos nomes!",
  ui_story_5063_50630102_48_dialog_content = "Então, você é considerado culpado?",
  ui_story_5063_50630102_49_dialog_content = "Cada julgamento proferido pelo Tribunal de Justiça é sancionado pelo Deus da Luz, sem absolutamente nenhuma margem para erro.",
  ui_story_5063_50630102_50_dialog_content = "Sendo uma parte culpada, você se recusou a admitir seu erro e enfrentar a punição e invadiu ilegalmente o Tribunal de Justiça, profanando nossos julgamentos sagrados...",
  ui_story_5063_50630102_51_dialog_content = "Você é simplesmente hediondo e merece ser punido ainda mais!",
  ui_story_5063_50630102_52_dialog_content = "...",
  ui_story_5063_50630102_53_dialog_content = "Humph! Como esperado, eu não deveria ter depositado minhas esperanças em Lumópolis desde o início!",
  ui_story_5063_50630102_54_dialog_content = "Sentar-se no Tribunal de Justiça e se exibir não significa que você realmente incorpora a justiça absoluta.",
  ui_story_5063_50630102_55_dialog_content = "Você vai ver. Farei justiça do meu próprio jeito.",
  ui_story_5063_50630102_56_dialog_content = "Isso é ultrajante!!!",
  ui_story_5063_50630102_57_dialog_content = "Cavaleiro da Justiça, por que você ainda está parado aí?",
  ui_story_5063_50630102_58_dialog_content = "Cavaleiro da Justiça Irridon, às suas ordens!",
  ui_story_5063_50630102_59_dialog_content = "Vá e prenda a louca! Não me decepcione de novo!",
  ui_story_5063_50630102_60_dialog_content = "Sim, Juiz Chefe!",
  ui_story_5063_50630201_1_dialog_content = "Espere aí, pare aí!",
  ui_story_5063_50630201_2_dialog_content = "Renda-se agora e você pode ter a chance de uma sentença mais leve.",
  ui_story_5063_50630201_3_dialog_content = "Ah? Então me diga, qual crime eu realmente cometi e por que você está me prendendo?",
  ui_story_5063_50630201_4_dialog_content = "Ao invadir o Salão da Justiça, você interrompeu o processo judicial e violou a santidade do local. Esta é a sua primeira ofensa.",
  ui_story_5063_50630201_5_dialog_content = "Sua segunda, como você mesmo gentilmente apontou, é que você é um fugitivo da lei.",
  ui_story_5063_50630201_6_dialog_content = "Por ordem da própria Juíza Chefe, você está preso. A segurança e a integridade das leis de Lumópolis devem ser mantidas!",
  ui_story_5063_50630201_7_dialog_content = "Heh, toda essa conversa sobre \"segurança\" e \"leis\", mas você não entende nem metade disso!",
  ui_story_5063_50630201_8_dialog_content = "Você nunca sequer pensou sobre por que deveria obedecer a esses chamados comandos...",
  ui_story_5063_50630201_9_dialog_content = "No final do dia, você é apenas um carrasco alimentado por esta cidade aparentemente imaculada!",
  ui_story_5063_50630201_10_dialog_content = "Você deve estar realmente louco para insultar um Cavaleiro da Justiça assim...!",
  ui_story_5063_50630201_11_dialog_content = "O que mais posso fazer? Você não ouviria mesmo. Você nem me conhece, mas já está cheio de preconceitos...",
  ui_story_5063_50630201_12_dialog_content = "A cidade não melhorou. Hmph, mesmo que eu costumava fazer parte dela...",
  ui_story_5063_50630201_13_dialog_content = "Quando a faca não está na sua garganta, você nunca saberá como é ser levado a um beco sem saída por preconceito e arrogância!",
  ui_story_5063_50630201_14_dialog_content = "Você está disposto a me contar o que aconteceu com você?",
  ui_story_5063_50630201_15_dialog_content = "Que pena, já é tarde demais agora. Heh, olha, eles já estão aqui.",
  ui_story_5063_50630201_16_dialog_content = "Proteção! Lealdade! Glória!",
  ui_story_5063_50630201_17_dialog_content = "Você está aqui para me ajudar a prender o fugitivo? Se sim, você chegou bem na hora—",
  ui_story_5063_50630201_18_dialog_content = "Ataque!",
  ui_story_5063_50630201_19_dialog_content = "*Tosse* O-O que você...?",
  ui_story_5063_50630302_1_dialog_content = "O que está acontecendo? Por que aqueles guardas desapareceram quando foram atacados? Estou tão confuso...",
  ui_story_5063_50630302_2_dialog_content = "Aquela mulher de manto preto também desapareceu rapidamente. Onde ela poderia ter ido?",
  ui_story_5063_50630302_3_dialog_content = "<color=#e8d9bb>Tum!</color>",
  ui_story_5063_50630302_4_dialog_content = "Urgh! M-Minhas desculpas!",
  ui_story_5063_50630302_5_dialog_content = "Eu estava correndo tão rápido que não te notei ali... Você está bem?",
  ui_story_5063_50630302_6_dialog_content = "Hum...",
  ui_story_5063_50630302_7_dialog_content = "E-Estou bem. Por favor, não se culpe, senhora cavaleira.",
  ui_story_5063_50630302_8_dialog_content = "Eu também estava com pressa e não consegui prestar atenção ao meu redor...",
  ui_story_5063_50630302_9_dialog_content = "Se for o caso, eu deveria ser o único a me desculpar!",
  ui_story_5063_50630302_10_dialog_content = "Por favor, não. Fui eu quem esbarrou em você, não o contrário.",
  ui_story_5063_50630302_11_dialog_content = "Você se machucou de alguma forma?",
  ui_story_5063_50630302_12_dialog_content = "Você deveria ser examinado por um médico, só por precaução. E eu pessoalmente cobrirei todas as despesas médicas.",
  ui_story_5063_50630302_13_dialog_content = "Foi apenas um tropeço e uma queda, senhora cavaleira... Agradeço sua generosidade, mas incomodar um médico por isso parece um pouco desnecessário.",
  ui_story_5063_50630302_14_dialog_content = "Além disso, você tem assuntos mais urgentes para tratar, certo? Eu me sentiria péssimo se minha própria tolice interrompesse seus nobres deveres.",
  ui_story_5063_50630302_15_dialog_content = "... Pelo menos deixe-me ajudá-lo a ficar de pé.",
  ui_story_5063_50630302_16_dialog_content = "Você também deixou cair algumas coisas. Tem certeza de que pegou tudo?",
  ui_story_5063_50630302_17_dialog_content = "Sim, Senhora Cavaleira. Nada parece estar faltando.",
  ui_story_5063_50630302_18_dialog_content = "Entendido. Se começar a se sentir mal, por favor, venha me procurar imediatamente. Meu nome é Irridon Novek.",
  ui_story_5063_50630302_19_dialog_content = "Ah, antes que eu me esqueça, você por acaso viu um personagem suspeito correndo por aqui agora mesmo?",
  ui_story_5063_50630302_20_dialog_content = "Um personagem suspeito? N-Não, eu acho que não...",
  ui_story_5063_50630302_21_dialog_content = "Hmm? Perdoe-me, senhorita, mas... há algo errado?",
  ui_story_5063_50630302_22_dialog_content = "Não tenha medo. Como um colega formado pela Dawn Academia, eu posso ser capaz de ajudar.",
  ui_story_5063_50630302_23_dialog_content = "Sério? Gr-Graças à Luz... Ainda sou apenas uma noviça em treinamento. Você pode me chamar de <color=#FFB400>Pam</color>.",
  ui_story_5063_50630302_24_dialog_content = "O motivo de eu estar com tanta pressa é—",
  ui_story_5063_50630302_25_dialog_content = "Encontramos ela, Senhora Nodirri! Está por aqui!",
  ui_story_5063_50630302_26_dialog_content = "Aí está você, Pam.",
  ui_story_5063_50630302_27_dialog_content = "Nosso professor nos pediu para recuperar o <color=#FFB400>Dawn Emblema</color> em sua posse. May Posso tê-lo de volta, por favor?",
  ui_story_5063_50630302_28_dialog_content = "Eu... acho que não, não.",
  ui_story_5063_50630302_29_dialog_content = "Huh? Isso... Isso dificilmente é sua decisão a tomar.",
  ui_story_5063_50630302_30_dialog_content = "Embora a academia tenha confiado a você esse emblema para este semestre, ele não pertence verdadeiramente a você. Dawn Emblemas são feitos para serem passados entre os estudantes.",
  ui_story_5063_50630302_31_dialog_content = "Considerando que este é o último dia do semestre, você não tem escolha a não ser devolvê-lo. Caso contrário... Como vou explicar isso ao nosso professor?",
  ui_story_5063_50630302_32_dialog_content = "Por que você não pode simplesmente devolver?",
  ui_story_5063_50630302_33_dialog_content = "Se você gosta tanto assim, reconquiste-o no próximo semestre.",
  ui_story_5063_50630302_34_dialog_content = "Você poderia pelo menos se explicar para nós, Pam.",
  ui_story_5063_50630302_35_dialog_content = "Não posso devolvê-lo... Porque o emblema foi roubado.",
  ui_story_5063_50630302_36_dialog_content = "O que? Mas como? Como você pôde permitir que algo tão precioso fosse roubado?!",
  ui_story_5063_50630302_37_dialog_content = "Eu...",
  ui_story_5063_50630302_38_dialog_content = "Por que você diz que foi \"roubado\"?",
  ui_story_5063_50630302_39_dialog_content = "Está tentando esconder que perdeu isso acidentalmente?",
  ui_story_5063_50630302_40_dialog_content = "Ou talvez você queira ficar com ele para si mesmo! Quer dizer, esse emblema é de ouro maciço e vale bastante.",
  ui_story_5063_50630302_41_dialog_content = "Por favor, acalmem-se, todos. Como um Cavaleiro da Justiça, eu também já fui um estudante da Dawn Academia.",
  ui_story_5063_50630302_42_dialog_content = "Se o Dawn Emblema da Pam foi realmente roubado, então isso é agora um assunto criminal digno de investigação!",
  ui_story_5063_50630302_43_dialog_content = "Fique tranquila, Pam, não descansarei até que o culpado seja capturado e levado à justiça.",
  ui_story_5063_50630302_44_dialog_content = "Verdade seja dita, há alguém que eu suspeito que tenha roubado...",
  ui_story_5063_50630302_45_dialog_content = "É uma das minhas colegas de classe. Para evitar causar uma cena, eu queria confrontá-la em particular.",
  ui_story_5063_50630302_46_dialog_content = "Quem sabe se realmente existe tal pessoa? Como saber se você não está apenas inventando tudo?",
  ui_story_5063_50630302_47_dialog_content = "Você tem razão... A Pam está toda gaguejando como se estivesse escondendo algo.",
  ui_story_5063_50630302_48_dialog_content = "Se realmente houver alguém suspeito, fale e nós todos te ajudaremos a recuperar.",
  ui_story_5063_50630302_49_dialog_content = "Eu...",
  ui_story_5063_50630302_50_dialog_content = "Não tenha medo, Pam. Conte-nos, e nós iremos recuperar o Emblema Dawn e provar sua inocência!",
  ui_story_5063_50630302_51_dialog_content = "Na verdade... Eu encontrei algo perto do local onde meu emblema desapareceu. Era um lenço pertencente a um dos meus colegas de classe.",
  ui_story_5063_50630302_52_dialog_content = "Hã? Por que está me olhando?",
  ui_story_5063_50630302_53_dialog_content = "Porque o lenço pertence a você, Nodirri.",
  ui_story_5063_50630302_54_dialog_content = "Está me acusando de algo?",
  ui_story_5063_50630302_55_dialog_content = "Na verdade, eu perdi aquele lenço há alguns dias atrás... Além disso, não é como se eu nunca tivesse tido o emblema antes!",
  ui_story_5063_50630302_56_dialog_content = "Apenas pessoas pobres encontrariam valor em roubar um emblema de ouro maciço como esse.",
  ui_story_5063_50630302_57_dialog_content = "Como um nobre de Lumópolis, por que eu me rebaixaria a algo tão vergonhoso quanto roubo? Minha família já possui riqueza mais do que suficiente.",
  ui_story_5063_50630302_58_dialog_content = "Também acho estranho, mas...",
  ui_story_5063_50630302_59_dialog_content = "Será que estou enganado?",
  ui_story_5063_50630302_60_dialog_content = "Pam... Eu nunca imaginei você como esse tipo de vilã. Você está claramente desviando a culpa de si mesma, não é?",
  ui_story_5063_50630302_61_dialog_content = "Eu não estou! Noite Branca lá no alto, eu juro que cada palavra que eu falei é a verdade. Se eu estiver mentindo, que o Deus da Luz me fulmine onde eu estou!",
  ui_story_5063_50630302_62_dialog_content = "Você por acaso se lembra do que aconteceu antes e depois de seu emblema desaparecer?",
  ui_story_5063_50630302_63_dialog_content = "Sim, eu estava na sala de estudo individual quando o tirei do meu vestido. Eu planejava devolver para minha professora.",
  ui_story_5063_50630302_64_dialog_content = "Mas de repente, ouvi um gatinho chorando de dor do lado de fora da janela. Saí e procurei por toda parte, mas não consegui encontrá-lo.",
  ui_story_5063_50630302_65_dialog_content = "Quando voltei para o quarto, meu Dawn Emblema havia desaparecido. A única coisa que encontrei foi aquele lenço...",
  ui_story_5063_50630302_66_dialog_content = "Entendi. Por favor, deixe a investigação comigo então.",
  ui_story_5063_50630303_1_dialog_content = "<color=#e8d9bb>Na grama verdejante da Academia Dawn, algo brilha intensamente.</color>",
  ui_story_5063_50630303_2_dialog_content = "<color=#e8d9bb>Irridon cuidadosamente afasta a vegetação e descobre uma pena dourada.</color>",
  ui_story_5063_50630303_3_dialog_content = "Uma <color=#FFB400>pena</color>?",
  ui_story_5063_50630303_4_dialog_content = "É daquela época...",
  ui_story_5063_50630303_5_dialog_content = "Então, o que a poderosa e importante Irridon queria com você agora há pouco?",
  ui_story_5063_50630303_6_dialog_content = "Ela disse que me viu em apuros sem uma caneta, então me emprestou sua pena dourada.",
  ui_story_5063_50630303_7_dialog_content = "É apenas uma pena dourada, e todo mundo tem uma. O que há para se exibir?",
  ui_story_5063_50630303_8_dialog_content = "Exatamente. E lembra como ela anda por aí com aquela cara indiferente, agindo como se fosse toda poderosa e superior?",
  ui_story_5063_50630303_9_dialog_content = "Ela só conseguiu essas notas por causa do <color=#FFB400>pai</color> dela. De qualquer forma, você não acha nojento usar as coisas dela?",
  ui_story_5063_50630303_10_dialog_content = "É por isso que eu joguei fora há muito tempo...",
  ui_story_5063_50630303_11_dialog_content = "Bem feito.",
  ui_story_5063_50630303_12_dialog_content = "Nunca pensei que encontraria isso novamente depois de todos esses anos.",
  ui_story_5063_50630303_13_dialog_content = "Espere... Já faz tanto tempo assim? Por que não consigo me lembrar?",
  ui_story_5063_50630303_14_dialog_content = "Talvez seja melhor eu esquecer, afinal.",
  ui_story_5063_50630304_1_dialog_content = "Hmm? Este boletim de notas está quase perfeito... Isso é raro de se ver, mesmo na Dawn Academia.",
  ui_story_5063_50630304_2_dialog_content = "Quem poderia ter esquecido algo tão importante no pátio da academia? Mal consigo distinguir o nome que está nele...",
  ui_story_5063_50630304_3_dialog_content = "\"<color=#FFB400>Irridon Novek</color>\"? Espere... Isso é meu!",
  ui_story_5063_50630304_4_dialog_content = "...",
  ui_story_5063_50630304_5_dialog_content = "No começo, achei que isso deixaria meu pai feliz.",
  ui_story_5063_50630304_6_dialog_content = "Mas quando eu mostrei isso a ele, sua expressão não mudou nem um pouco.",
  ui_story_5063_50630304_7_dialog_content = "Para ele, isso era algo que eu deveria realizar. Ele me disse para não desperdiçar o tempo dele.",
  ui_story_5063_50630304_8_dialog_content = "Eu já estava preparado para esse tipo de resposta... Mas naquele dia, ele se afastou do trabalho apenas para me criticar.",
  ui_story_5063_50630304_9_dialog_content = "Ele me perguntou por que eu não tinha amigos na Dawn Academia e por que eu não mantive uma posição melhor entre meus colegas.",
  ui_story_5063_50630304_10_dialog_content = "Meu pai acreditava que eu não estava dando o meu melhor e que minhas ações manchariam o bom nome da nossa família. Ele estava preocupado que seu trabalho seria afetado...",
  ui_story_5063_50630304_11_dialog_content = "Eu não sabia o que dizer. Tudo o que eu podia fazer era baixar minha cabeça em vergonha.",
  ui_story_5063_50630304_12_dialog_content = "\"Inútil!\" ... Por muito tempo depois, essa foi a maneira mais comum do meu pai se dirigir a mim.",
  ui_story_5063_50630304_13_dialog_content = "Eu sou realmente inútil...?",
  ui_story_5063_50630304_14_dialog_content = "Não tentei o meu melhor...?",
  ui_story_5063_50630601_1_dialog_content = "Como vai a investigação, Cavaleiro da Justiça?",
  ui_story_5063_50630601_2_dialog_content = "Você parece ser um novo recruta mesmo... Eu odeio pressionar você assim, mas o tempo está acabando.",
  ui_story_5063_50630601_3_dialog_content = "Talvez eu deva apenas relatar isso aos nossos professores e deixar que a academia cuide do assunto?",
  ui_story_5063_50630601_4_dialog_content = "Isso não será necessário. Eu já fiz um progresso considerável, mas ainda tenho uma última pergunta para você. Me diga, quando exatamente você perdeu seu lenço?",
  ui_story_5063_50630601_5_dialog_content = "Eu já não respondi a essa pergunta? Eu te disse antes, eu perdi isso alguns dias atrás.",
  ui_story_5063_50630601_6_dialog_content = "O guarda da academia viu você abrir a porta da sala de estudos com seu lenço mais cedo. Gostaria de explicar?",
  ui_story_5063_50630601_7_dialog_content = "Eu pensei que ele estivesse dormindo o tempo todo...",
  ui_story_5063_50630601_8_dialog_content = "Então você admite que entrou na sala de estudo individual mais cedo hoje?",
  ui_story_5063_50630601_9_dialog_content = "Espere... Eu sinto algo estranho. Você esteve do lado da Pam desde o começo, não é? Me diga, que tipo de acordo você fez com ela?",
  ui_story_5063_50630601_10_dialog_content = "Você nem se deu ao trabalho de procurar nela o item desaparecido quando todos estavam presentes!",
  ui_story_5063_50630601_11_dialog_content = "Mas eu... eu só pedi ajuda à cavaleira porque não conseguia encontrar meu Dawn Emblema!",
  ui_story_5063_50630601_12_dialog_content = "Você diz isso, mas como sabemos que você não está mentindo?",
  ui_story_5063_50630601_13_dialog_content = "E-eu não tenho nada a esconder! Me reviste, se for necessário!",
  ui_story_5063_50630601_14_dialog_content = "Como desejar.",
  ui_story_5063_50630601_15_dialog_content = "Todos, por precaução, vamos seguir em frente e procurar.",
  ui_story_5063_50630601_16_dialog_content = "E não se esqueça da bolsa da Pam!",
  ui_story_5063_50630601_17_dialog_content = "Encontrei algo... O que é isso?!",
  ui_story_5063_50630601_18_dialog_content = "Um Emblema Dawn?",
  ui_story_5063_50630601_19_dialog_content = "Então estava com você o tempo todo!",
  ui_story_5063_50630601_20_dialog_content = "Seu mentiroso sem vergonha... Esse emblema realmente significa tanto para você?",
  ui_story_5063_50630601_21_dialog_content = "N-Não... Como pode ser? Não estava na minha mochila quando eu procurei...",
  ui_story_5063_50630601_22_dialog_content = "O que poderia ter te levado a fazer uma coisa dessas? Conte-nos, e talvez estejamos dispostos a entender.",
  ui_story_5063_50630601_23_dialog_content = "Presidente Nodirri, não simpatize com ela. Ela já quebrou as leis de Lumópolis!",
  ui_story_5063_50630601_24_dialog_content = "Cavaleiro da Justiça, o que está esperando? Prenda-a já!",
  ui_story_5063_50630601_25_dialog_content = "O caso ainda está em investigação.",
  ui_story_5063_50630601_26_dialog_content = "O quê?",
  ui_story_5063_50630601_27_dialog_content = "Este Emblema Dawn não é feito de ouro maciço... Na verdade, parece ser uma <color=#FFB400>falsificação</color>.",
  ui_story_5063_50630601_28_dialog_content = "Senhora Irridon... Isso não é uma falsificação, de forma alguma. Posso garantir que este é o emblema que eu perdi.",
  ui_story_5063_50630601_29_dialog_content = "Não pense que não podemos ver através da sua farsa! Você plantou essa falsificação na sua mochila para poder manter a verdadeira escondida, não foi?!",
  ui_story_5063_50630601_30_dialog_content = "Você está enganado! O emblema dourado é tão precioso que eu estava preocupado se não cuidaria bem o suficiente dele...",
  ui_story_5063_50630601_31_dialog_content = "Então, eu solicitei um Dawn Emblema diferente da Academia, um que não fosse feito de ouro verdadeiro.",
  ui_story_5063_50630601_32_dialog_content = "Sei que este emblema tem pouco valor, mas a honra que ele me traz é mais do que suficiente.",
  ui_story_5063_50630601_33_dialog_content = "Agora você está inventando coisas! Eu nunca ouvi falar da Dawn Academia fornecendo emblemas falsos aos seus alunos!",
  ui_story_5063_50630601_34_dialog_content = "Mas eu não estou! É só perguntar ao nosso professor... Você vai ver que estou dizendo a verdade se fizer isso!",
  ui_story_5063_50630601_35_dialog_content = "Se este emblema realmente não tem valor monetário, então Pam não teria motivo para roubá-lo.",
  ui_story_5063_50630601_36_dialog_content = "Presidente Nodirri, vamos perguntar ao professor como lidar com isso?",
  ui_story_5063_50630601_37_dialog_content = "Já chega, todos vocês!",
  ui_story_5063_50630601_38_dialog_content = "Se dinheiro não é o motivo dela, então só pode ser uma coisa... É calúnia! Ela tem tentado manchar minha reputação desde o início!",
  ui_story_5063_50630601_39_dialog_content = "Comigo fora do caminho, a Pam não teria problemas para conseguir um lugar no Templo de Lumópolis como uma noviça! Não é verdade?!",
  ui_story_5063_50630601_40_dialog_content = "Th-Não é nada disso...!",
  ui_story_5063_50630601_41_dialog_content = "Você foi tola em fazer isso, Pam. Suas ações só te afastaram cada vez mais do templo e de sua glória.",
  ui_story_5063_50630601_42_dialog_content = "Além disso, alguém de seu baixo status não tem o direito de ascender ao Templo de Lumópolis!",
  ui_story_5063_50630601_43_dialog_content = "E mesmo que você conseguisse entrar, os outros nobres e seus filhos te pisariam até virar pó! Você é realmente tão ingênuo?!",
  ui_story_5063_50630601_44_dialog_content = "Algo não está certo. Quando esbarrei acidentalmente na Pam mais cedo, o conteúdo da mochila dela estava espalhado pelo chão.",
  ui_story_5063_50630601_45_dialog_content = "Eu não me lembro de ver este emblema entre os pertences dela que caíram, então como ele apareceu do nada?",
  ui_story_5063_50630601_46_dialog_content = "A menos que... Alguém tenha colocado isso na minha mochila depois do nosso encontro?",
  ui_story_5063_50630601_47_dialog_content = "É uma coisa fazer uma brincadeira infantil com os outros, mas envolver um Cavaleiro da Justiça de Lumópolis no assunto? Eles não têm vergonha?!",
  ui_story_5063_50630601_48_dialog_content = "Quem quer que seja responsável por isso deve confessar imediatamente, ou não mostrarei nenhuma indulgência.",
  ui_story_5063_50630601_49_dialog_content = "Senhora Irridon!",
  ui_story_5063_50630601_50_dialog_content = "Meu Emblema Dawn está de volta em minha posse e não parece estar danificado de forma alguma. Isso é mais do que suficiente para me deixar tranquilo.",
  ui_story_5063_50630601_51_dialog_content = "Tudo bem, mas a questão se tornou mais complicada do que isso.",
  ui_story_5063_50630601_52_dialog_content = "Mas... Mas é possível que eu simplesmente não tenha percebido isso antes, não é?",
  ui_story_5063_50630601_53_dialog_content = "Hmph, parece ser o caso mesmo. Você deveria ser mais cuidadoso da próxima vez, para não desperdiçar o tempo de todos com suas palhaçadas infantis novamente. Vamos, pessoal!",
  ui_story_5063_50630601_54_dialog_content = "E aí? Você vem ou não?!",
  ui_story_5063_50630601_55_dialog_content = "Sim, Presidente Nodirri.",
  ui_story_5063_50630601_56_dialog_content = "Por que você escolheu deixá-la ir, Pam? Ela era claramente a culpada!",
  ui_story_5063_50630601_57_dialog_content = "Porque ela não cometeu nada verdadeiramente hediondo... Foi apenas um lapso momentâneo de escrúpulos, nada mais. Além disso, tenho certeza de que o coração dela já está cheio de culpa e remorso.",
  ui_story_5063_50630601_58_dialog_content = "O Deus da Luz nos ensina a sermos perdoados. Como uma freira em treinamento, não tenho o direito de ir contra nossos ensinamentos.",
  ui_story_5063_50630601_59_dialog_content = "Acredito que o Deus da Luz guiará seus passos e a ajudará a se tornar uma pessoa melhor... Noite Branca no alto.",
  ui_story_5063_50630601_60_dialog_content = "É mesmo? Heh, muito bem então. Mesmo que esse incidente nunca tivesse acontecido, tenho certeza de que o Templo de Lumópolis teria escolhido você para ficar.",
  ui_story_5063_50630601_61_dialog_content = "Huh? E-Eles ainda não tomaram uma decisão, sabe...",
  ui_story_5063_50630601_62_dialog_content = "Eu só queria ter um colega de classe como você quando eu ainda estava na Academia. Talvez nós... Poderíamos ter sido amigos.",
  ui_story_5063_50630601_63_dialog_content = "Mas você é uma cavaleira tão valente e dedicada, Senhora Irridon! Tenho certeza de que você tinha muitos amigos na Academia!",
  ui_story_5063_50630601_64_dialog_content = "Na verdade, bem o contrário. Todos achavam que minhas conquistas eram apenas resultado de ser filha do meu pai. Dizer que eu era detestada pelos meus colegas seria um eufemismo.",
  ui_story_5063_50630601_65_dialog_content = "Até meu pai começou a acreditar nos rumores que espalharam sobre mim. Foi... Um período muito solitário no meu passado.",
  ui_story_5063_50630601_66_dialog_content = "Então vamos ser amigos agora!",
  ui_story_5063_50630601_67_dialog_content = "Podemos não ser colegas de classe, mas ainda podemos ser ótimos amigos! Nosso encontro deve ter sido planejado perfeitamente pelo destino!",
  ui_story_5063_50630601_68_dialog_content = "Planejado... Pelo destino?",
  ui_story_5063_50630601_69_dialog_content = "Claro! Quem mais poderia ter me resgatado senão a Senhora Irridon dos Cavaleiros da Justiça?",
  ui_story_5063_50630601_70_dialog_content = "B-Bem, há muitos outros cavaleiros—",
  ui_story_5063_50630601_71_dialog_content = "Não é um crime reconhecer seus próprios talentos e valor, Senhora Irridon. Não concorda?",
  ui_story_5063_50630601_72_dialog_content = "Hã? N-Não, eu acho que não é ilegal...",
  ui_story_5063_50630601_73_dialog_content = "Agora que penso nisso, acredito que Pittman também quer se tornar um Cavaleiro da Justiça!",
  ui_story_5063_50630601_74_dialog_content = "<color=#FFB400>Pittman</color>? Esse nome me parece um pouco familiar...",
  ui_story_5063_50630601_75_dialog_content = "Ele é um dos meus amigos. Ele ficaria absolutamente empolgado em conhecer um Cavaleiro da Justiça tão excepcional como você, sabia!",
  ui_story_5063_50630601_76_dialog_content = "Você acha que eu sou... Excepcional?",
  ui_story_5063_50630601_77_dialog_content = "Claro! Com certeza vou apresentar vocês dois um dia.",
  ui_story_5063_50630601_78_dialog_content = "Nossa, olha a hora! Ainda preciso visitar meu avô em sua casa...",
  ui_story_5063_50630601_79_dialog_content = "Perdoe-me, Senhora Irridon, mas preciso ir agora!",
  ui_story_5063_50630601_80_dialog_content = "Na próxima vez que nos encontrarmos, prometo retribuir adequadamente por tudo o que você fez!",
  ui_story_5063_50630701_1_dialog_content = "Eu sou... Realmente um excepcional Cavaleiro da Justiça?",
  ui_story_5063_50630701_2_dialog_content = "Que tipo de Cavaleiro da Justiça permite que um criminoso saia impune...",
  ui_story_5063_50630701_3_dialog_content = "Devo relatar isso ao Juiz Chefe?",
  ui_story_5063_50630701_4_dialog_content = "Vá e prenda a louca! Não me decepcione de novo!",
  ui_story_5063_50630701_5_dialog_content = "Eu só a decepcionaria ainda mais do que já fiz...",
  ui_story_5063_50630701_6_dialog_content = "Ela provavelmente acha que sou inútil, assim como meu pai.",
  ui_story_5063_50630701_7_dialog_content = "Na verdade... Eles podem até me expulsar do Tribunal de Justiça por isso...",
  ui_story_5063_50630701_8_dialog_content = "...",
  ui_story_5063_50630701_9_dialog_content = "Hã? É ela!!",
  ui_story_5063_50630701_10_dialog_content = "Ela está tentando escapar para o Pátio de Lumopolis pela Escadaria para os Céus...",
  ui_story_5063_50630701_11_dialog_content = "Bom, pelo menos os Jardins de Lumópolis estão a salvo de suas ações!",
  ui_story_5063_50630701_12_dialog_content = "Espere, isso não é motivo para alívio! Eu tenho que pegá-la!",
  ui_story_5063_50630701_13_dialog_content = "Proteção! Lealdade! Glória!",
  ui_story_5063_50630701_14_dialog_content = "Aqueles soldados estranhos estão de volta novamente!",
  ui_story_5063_50630701_15_dialog_content = "Por favor, fique fora do meu caminho! Você está atrapalhando minha perseguição a um criminoso!",
  ui_story_5063_50630802_1_dialog_content = "Pare-!",
  ui_story_5063_50630802_2_dialog_content = "Ela desapareceu de novo? Devo perguntar às pessoas mais à frente se viram ela.",
  ui_story_5063_50630802_3_dialog_content = "Sempre podemos ir ao Tribunal de Justiça, se necessário!",
  ui_story_5063_50630802_4_dialog_content = "Exatamente meus pensamentos. Juro que vou chegar ao fundo disso!",
  ui_story_5063_50630802_5_dialog_content = "Desculpe-me, bons senhores, mas algum de vocês notou uma mulher suspeita de preto correndo por esta área?",
  ui_story_5063_50630802_6_dialog_content = "Eu não vi uma mulher de preto, mas esse cara na nossa frente, Jerry, parece muito suspeito para mim.",
  ui_story_5063_50630802_7_dialog_content = "Aqui está sua chance, Senhor Prefeito! Vá em frente, compartilhe seus pensamentos com o Tribunal de Justiça!",
  ui_story_5063_50630802_8_dialog_content = "Abordar pessoas inocentes na rua, apenas para interrogá-las cegamente... Isso também faz parte da educação da nobreza?!",
  ui_story_5063_50630802_9_dialog_content = "Conheça seu lugar, servo! A educação dos nobres dificilmente diz respeito a um simples camponês como você!",
  ui_story_5063_50630802_10_dialog_content = "Distúrbios públicos são uma violação direta da lei de Lumópolis. Sugiro que vocês dois se acalmem imediatamente.",
  ui_story_5063_50630802_11_dialog_content = "Agora, qual parece ser o problema? Ficarei mais do que feliz em mediar.",
  ui_story_5063_50630802_12_dialog_content = "Você é um Cavaleiro da Justiça, certo? Por favor, perdoe minha explosão de agora há pouco.",
  ui_story_5063_50630802_13_dialog_content = "Você chegou na hora certa. Eu gostaria de fazer uma denúncia contra este servo descaradamente ganancioso! Você vai me ajudar, não vai?",
  ui_story_5063_50630802_14_dialog_content = "Novamente, por favor, acalme-se e me conte exatamente o que aconteceu.",
  ui_story_5063_50630802_15_dialog_content = "Hoje, meu pai idoso faleceu <color=#FFB400>repentina e misteriosamente</color>.",
  ui_story_5063_50630802_16_dialog_content = "Assim que recebi a notícia, vim cuidar dos bens dele, mas este homem aqui - um servo empregado por meu pai, conhecido como Jerry - se recusa a me deixar entrar na propriedade.",
  ui_story_5063_50630802_17_dialog_content = "Ele me apresentou este estranho <color=#FFB400>testamento</color>, dizendo que meu pai legou seu título e propriedade inteiramente para ele.",
  ui_story_5063_50630802_18_dialog_content = "A própria ideia de um pai privar seu próprio filho do nome e status de sua família...",
  ui_story_5063_50630802_19_dialog_content = "S-Se isso fosse verdade, nossa família seria reduzida a plebeus comuns!",
  ui_story_5063_50630802_20_dialog_content = "É absolutamente absurdo, você não concorda? Como cavaleiro, tenho certeza que sim!",
  ui_story_5063_50630802_21_dialog_content = "A menos que haja algo suspeito, é realmente muito incomum um nobre renunciar a todo o seu legado, especialmente para...",
  ui_story_5063_50630802_22_dialog_content = "Para um servo humilde? Era isso que você ia dizer, certo?",
  ui_story_5063_50630802_23_dialog_content = "Estou certo em presumir que você nasceu em uma vida de riqueza e nobreza, senhora cavaleira? Uma vida onde todos os seus desejos e necessidades são satisfeitos num estalar de dedos?",
  ui_story_5063_50630802_24_dialog_content = "Independente da minha origem, sou um Cavaleiro da Justiça de Lumopolis e tenho o dever de tratar ambas as partes de maneira justa e equitativa.",
  ui_story_5063_50630802_25_dialog_content = "Agora, por favor, compartilhe seu lado da questão.",
  ui_story_5063_50630802_26_dialog_content = "Embora seja verdade que o Senhor Major é filho do meu mestre, os dois sempre estiveram em desacordo um com o outro, e o Senhor Major raramente visitava meu mestre enquanto ele estava vivo.",
  ui_story_5063_50630802_27_dialog_content = "Até o momento em que ele deu seu último suspiro, eu fui quem cuidou do meu mestre, dia e noite.",
  ui_story_5063_50630802_28_dialog_content = "Apesar da minha origem humilde, meu mestre sempre me incentivou a melhorar. Eventualmente, ele começou a me considerar como seu próprio filho.",
  ui_story_5063_50630802_29_dialog_content = "Ele redigiu este testamento para provar sua sinceridade e dissipar minhas dúvidas. Você verá que está totalmente de acordo com a lei de Lumopolis...",
  ui_story_5063_50630802_30_dialog_content = "Eu não falei nada além da verdade! Se algo que eu disse for mentira, que eu seja castigado pelo Deus da Luz!",
  ui_story_5063_50630802_31_dialog_content = "Não se deixe enganar pelas palavras floridas dele, senhora cavaleira. O Deus da Luz jamais ouviria uma única palavra de sua boca mentirosa.",
  ui_story_5063_50630802_32_dialog_content = "Quanto às minhas raras visitas, meu pai me deu pouca escolha. O homem simplesmente se recusava a me ver.",
  ui_story_5063_50630802_33_dialog_content = "E antes que você comece a suspeitar de algo, eu nunca prejudiquei meu pai de forma alguma. Ele sempre foi muito rígido comigo e suas expectativas sempre foram tão altas...",
  ui_story_5063_50630802_34_dialog_content = "Em seus olhos, eu não era nada além de um filho indolente, ignorante e complacente.",
  ui_story_5063_50630802_35_dialog_content = "Apesar dos meus melhores esforços para atender às suas exigências, ele nunca ficou satisfeito. Nem uma vez sequer ele me reconheceu como uma pessoa valiosa.",
  ui_story_5063_50630802_36_dialog_content = "Apesar de sua insatisfação comigo, sei que meu pai nunca teria deixado um testamento assim.",
  ui_story_5063_50630802_37_dialog_content = "E isso é porque ele era muito apegado à sua neta, minha própria filha.",
  ui_story_5063_50630802_38_dialog_content = "Ela o visitava frequentemente para lhe fazer companhia e garantir que ele estava bem. Negar-me é uma coisa, mas ele nunca privaria sua neta de sua herança legítima!",
  ui_story_5063_50630802_39_dialog_content = "Você também conhece a neta do seu mestre, Jerry?",
  ui_story_5063_50630802_40_dialog_content = "Sim. Eu também estava curioso para saber por que meu mestre não deixou sua fortuna para ela, mas ele disse que ela tinha pouca necessidade disso.",
  ui_story_5063_50630802_41_dialog_content = "Hahahaha! Que completamente ridículo! Ouso dizer que nunca ouvi uma mentira mais patética em toda a minha vida!",
  ui_story_5063_50630802_42_dialog_content = "Admita! Isso tudo é apenas um esquema vil para nos roubar nossos meios de subsistência!",
  ui_story_5063_50630802_43_dialog_content = "Senhor Prefeito, você já deveria saber que eu não sou um homem motivado pela riqueza. Se fosse, nunca teria ficado ao lado de seu pai por tanto tempo.",
  ui_story_5063_50630802_44_dialog_content = "No entanto, meu mestre deixou muito claro para mim que esses são seus últimos desejos, e não tenho intenção de desonrá-los!",
  ui_story_5063_50630802_45_dialog_content = "(Sinto que já vi um dilema semelhante antes. Será que foi um caso dos meus dias de academia?)",
  ui_story_5063_50630802_46_dialog_content = "(Eu ainda não consigo me lembrar... Ugh, por que me sinto tão tonto?)",
  ui_story_5063_50630802_47_dialog_content = "Senhora Irridon?",
  ui_story_5063_50630802_48_dialog_content = "Pai, Jerry... O que vocês estão fazendo aqui? Vocês se conhecem?",
  ui_story_5063_50630802_49_dialog_content = "Você conhece esse cavaleiro, Pam?",
  ui_story_5063_50630802_50_dialog_content = "Sim, pai. A senhora Irridon é uma amiga minha que recentemente me ajudou com um problema. Na verdade, eu estava pensando em convidá-la para jantar...",
  ui_story_5063_50630802_51_dialog_content = "Isso não será um problema, certo pai? Afinal, vocês dois já parecem se conhecer.",
  ui_story_5063_50630802_52_dialog_content = "Agora, se todos puderem me dar licença, estou preocupado com meu avô. Ninguém atendeu a porta quando fui visitá-lo agora há pouco... Alguém sabe por quê?",
  ui_story_5063_50630802_53_dialog_content = "Pam, seu avô... Não está mais conosco.",
  ui_story_5063_50630802_54_dialog_content = "<size=45>H-Ele faleceu?!</size>",
  ui_story_5063_50630802_55_dialog_content = "Mas o avô sempre foi tão saudável! Como isso pode ter acontecido?! Eu não acredito! Isso deve ser algum tipo de piada!",
  ui_story_5063_50630802_56_dialog_content = "Ele ainda não viu minha aceitação formal no Templo de Lumópolis, como ele pode simplesmente me deixar assim?",
  ui_story_5063_50630802_57_dialog_content = "Pai? Jerry? Por que estão com essas expressões no rosto? Por favor... Me digam que isso não é real...",
  ui_story_5063_50630802_58_dialog_content = "(Não posso me dar ao luxo de ignorar esse caso, especialmente porque afeta a Pam profundamente.)",
  ui_story_5063_50630802_59_dialog_content = "Pessoal, por favor aceitem minhas mais sinceras condolências...",
  ui_story_5063_50630802_60_dialog_content = "Permita-me lidar pessoalmente com a investigação deste assunto.",
  ui_story_5063_50630803_1_dialog_content = "<color=#e8d9bb>Durante a investigação de Irridon na casa do avô de Pam, ela encontra inesperadamente uma vara de apontar escondida em um canto, aparentemente discreta.</color>",
  ui_story_5063_50630803_2_dialog_content = "Um <color=#FFB400>pauzinho para apontar</color>...",
  ui_story_5063_50630803_3_dialog_content = "É exatamente igual ao do meu pai!",
  ui_story_5063_50630803_4_dialog_content = "Minhas mãos ainda lembram a ardência de cada erro que cometi.",
  ui_story_5063_50630803_5_dialog_content = "Essa dor fria, dura e ardente...",
  ui_story_5063_50630803_6_dialog_content = "Só de ver uma dessas varinhas apontadoras já é o suficiente para acelerar meu coração.",
  ui_story_5063_50630803_7_dialog_content = "De repente, me lembro daquela cena terrível: meu pai diante de mim, com as garras de um Eclipsite afundando profundamente em seu peito...",
  ui_story_5063_50630803_8_dialog_content = "Meu pai nunca se importou comigo, então por que ele sacrificaria sua própria vida por sua filha \"inútil\"?",
  ui_story_5063_50630803_9_dialog_content = "Ainda não entendo. É por isso que, mesmo agora, ainda tenho muito medo de passar pelo escritório dele...",
  ui_story_5063_50630803_10_dialog_content = "Uma vez que eu deixe de ser tão inútil e me torne um Cavaleiro da Justiça digno aos olhos do Juiz Chefe... Terei coragem de enfrentar meu pai então?",
  ui_story_5063_50630803_11_dialog_content = "O pai de Pam, Lorde Major, parece compartilhar uma história semelhante com seu próprio pai.",
  ui_story_5063_50630803_12_dialog_content = "Mas, pelo bem de sua filha, ele conseguiu acabar com esse ciclo vicioso em seu próprio tempo. Eu duvido que tenha sido fácil para ele.",
  ui_story_5063_50630803_13_dialog_content = "Senhor Major... Você se saiu bem.",
  ui_story_5063_50630803_14_dialog_content = "Quanto a mim... Eu preciso fazer o mesmo.",
  ui_story_5063_50630804_1_dialog_content = "É um arquivo oficial de caso jogado na beira da estrada? Que tipo de desajeitado descuidado poderia ter...",
  ui_story_5063_50630804_2_dialog_content = "Espere! Este é o arquivo do caso da minha investigação atual?!",
  ui_story_5063_50630804_3_dialog_content = "Parece que o juiz que preside este caso considerou o testamento de natureza duvidosa...",
  ui_story_5063_50630804_4_dialog_content = "O motivo é... Que a testemunha presente na assinatura do testamento era um servo, não um tabelião oficial. Portanto, o testemunho da testemunha não pôde ser legalmente aceito.",
  ui_story_5063_50630804_5_dialog_content = "Com o testamento considerado inválido, a distribuição do patrimônio do falecido ficou sob a jurisdição de nossas leis comuns de herança.",
  ui_story_5063_50630804_6_dialog_content = "Mas como isso pode ser? Eu preciso encontrar o juiz que supervisionou este caso e confrontá-lo sobre isso!",
  ui_story_5063_50630804_7_dialog_content = "Há uma assinatura na parte inferior...",
  ui_story_5063_50630804_8_dialog_content = "\"<color=#FFB400>Rodell Novek</color>\"?!",
  ui_story_5063_50630804_9_dialog_content = "Meu <color=#FFB400>pai</color> presidiu este caso?!",
  ui_story_5063_50630804_10_dialog_content = "Isso significa que eu tenho que dar o mesmo veredicto que ele...?",
  ui_story_5063_50630804_11_dialog_content = "É realmente a única maneira de conquistar a aceitação dele? Aceitando e obedecendo a cada palavra dele?",
  ui_story_5063_50630804_12_dialog_content = "De alguma forma...",
  ui_story_5063_50630804_13_dialog_content = "De alguma forma, eu não acho que esse foi o veredicto certo...",
  ui_story_5063_50631101_1_dialog_content = "(Embora as razões ainda não estejam claras, parece que o avô de Pam realmente tirou a própria vida. O ponto de controvérsia, então, gira em torno de seu testamento.)",
  ui_story_5063_50631101_2_dialog_content = "(Em forma e conteúdo, este testamento foi escrito em perfeita conformidade com as leis de herança de Lumopolis.)",
  ui_story_5063_50631101_3_dialog_content = "(A única discordância é que a testemunha não era nobre, mas um velho servo... No entanto, isso dificilmente é um motivo válido para negar a autenticidade de um testamento.)",
  ui_story_5063_50631101_4_dialog_content = "(Mas se o testamento for aceito pelo tribunal, Pam e sua família perderão seu status de nobres. Isso não afetaria o futuro dela também?)",
  ui_story_5063_50631101_5_dialog_content = "(Eu não quero arriscar nossa amizade por causa disso... O que devo fazer?)",
  ui_story_5063_50631101_6_dialog_content = "Senhora Irridon? Não estou me intrometendo, estou?",
  ui_story_5063_50631101_7_dialog_content = "Por favor, não entenda mal! Eu só quero dizer... Por favor, não deixe nosso conhecimento atrapalhar um julgamento justo!",
  ui_story_5063_50631101_8_dialog_content = "Noite Branca nas alturas. Como um Cavaleiro da Justiça de Lumópolis, você foi escolhido pelo Deus da Luz para servir o povo desta cidade de forma igualitária e sem preconceitos.",
  ui_story_5063_50631101_9_dialog_content = "Perdoe-me se pareço presunçoso, mas por favor... Não deixe nossa amizade manchar a santidade do julgamento justo!",
  ui_story_5063_50631101_10_dialog_content = "Pam...",
  ui_story_5063_50631101_11_dialog_content = "Meu pai me ensinou há muito tempo que um verdadeiro servidor da justiça é imparcial.",
  ui_story_5063_50631101_12_dialog_content = "Fique tranquilo, vou reunir as provas necessárias para fazer um julgamento justo e honesto!",
  ui_story_5063_50631101_13_dialog_content = "Já chegou a uma conclusão, senhora cavaleira?",
  ui_story_5063_50631101_14_dialog_content = "Também aguardo ansiosamente seu julgamento, milady!",
  ui_story_5063_50631101_15_dialog_content = "Finalmente cheguei a um veredito, sim.",
  ui_story_5063_50631101_16_dialog_content = "Noite Branca nas alturas! De acordo com as leis de Lumópolis sobre herança e testamentos finais, declaro que este testamento é legalmente válido.",
  ui_story_5063_50631101_17_dialog_content = "Mas a testemunha não era mais do que um mero servo! Certamente você notou essa violação flagrante, não é?!",
  ui_story_5063_50631101_18_dialog_content = "Seu julgamento descuidado abalará toda Lumopolis até seus alicerces!",
  ui_story_5063_50631101_19_dialog_content = "Não há lei em Lumopolis que proíba uma pessoa de atuar como testemunha com base apenas em sua condição econômica. Isso é apenas um boato que existe entre os membros da nobreza.",
  ui_story_5063_50631101_20_dialog_content = "Desde que uma pessoa seja honesta, diligente e livre de qualquer irregularidade legal, ela está perfeitamente apta a servir como uma testemunha confiável.",
  ui_story_5063_50631101_21_dialog_content = "Você... E se chama de Cavaleiro da Justiça de Lumópolis?!",
  ui_story_5063_50631101_22_dialog_content = "Pai, pare! Quando um grupo de estudantes nobres me acusou de roubar um Emblema Dawn da Academia, foi a Senhora Irridon quem descobriu a verdade por trás de suas ações!",
  ui_story_5063_50631101_23_dialog_content = "Nosso preconceito em relação ao Sr. Jerry não é diferente do preconceito que aqueles outros nobres demonstraram em relação a nós.",
  ui_story_5063_50631101_24_dialog_content = "De qualquer forma, eu confio na Senhora Irridon e em sua capacidade de proferir um julgamento justo e razoável.",
  ui_story_5063_50631101_25_dialog_content = "Você também não, Pam...",
  ui_story_5063_50631101_26_dialog_content = "Se este foi realmente o último desejo do avô, não temos escolha a não ser honrá-lo.",
  ui_story_5063_50631101_27_dialog_content = "Suspiro, como as coisas acabaram assim? E eu pensei que poderia te dar um pouco mais...",
  ui_story_5063_50631101_28_dialog_content = "Talvez o velho nunca tenha desejado um filho como eu, afinal.",
  ui_story_5063_50631101_29_dialog_content = "Isso não é verdade de jeito nenhum, pai! Eu sei que sempre houve uma grande distância entre nós...",
  ui_story_5063_50631101_30_dialog_content = "Mas o avô nunca reclamou ou falou mal de você sempre que eu visitava! Você também tinha seu próprio jeito silencioso de cuidar dele, não tinha?",
  ui_story_5063_50631101_31_dialog_content = "Se vocês dois tivessem dado aquele primeiro passo em direção um ao outro, tenho certeza de que poderiam ter diminuído a distância entre vocês!",
  ui_story_5063_50631101_32_dialog_content = "Pai…",
  ui_story_5063_50631101_33_dialog_content = "(Há uma distância intransponível semelhante entre meu pai e eu?)",
  ui_story_5063_50631101_34_dialog_content = "(Mesmo com as coisas como estão agora, meu veredicto ainda é completamente diferente do dele.)",
  ui_story_5063_50631101_35_dialog_content = "(Será que... Meu julgamento ainda está sendo afetado pelas minhas emoções?!)",
  ui_story_5063_50631101_36_dialog_content = "(Não foi minha amizade com Pam, mas meu desejo de me rebelar contra meu pai... Foi isso que me levou a dar esse veredicto!)",
  ui_story_5063_50631101_37_dialog_content = "Por que você ficou tão silenciosa, Senhora Irridon? Se é por causa da nossa situação... Então eu humildemente peço que você se abstenha de nos lamentar.",
  ui_story_5063_50631101_38_dialog_content = "Não é nada, apenas me lembrei do meu próprio pai. Se ele ainda estivesse conosco hoje... Será que ele teria dado um veredicto diferente?",
  ui_story_5063_50631101_39_dialog_content = "Entendi. Isso significa que você deseja ser mais como seu pai, Senhora Irridon?",
  ui_story_5063_50631101_40_dialog_content = "Nunca!",
  ui_story_5063_50631101_41_dialog_content = "Perdoe-me se me expressei mal, mas você é realmente tão contra essa ideia?",
  ui_story_5063_50631101_42_dialog_content = "Caso contrário, por que o julgamento do seu pai te preocuparia tanto?",
  ui_story_5063_50631101_43_dialog_content = "Eu...",
  ui_story_5063_50631101_44_dialog_content = "Você tem razão. Por que estou tão preocupado com o veredito que meu pai alcançaria? E por que me tornei um Cavaleiro da Justiça em primeiro lugar?",
  ui_story_5063_50631101_45_dialog_content = "<size=45>É isso! Prenda todos nesta casa!</size>",
  ui_story_5063_50631101_46_dialog_content = "<size=45>Isso!</size>",
  ui_story_5063_50631101_47_dialog_content = "A-ahn?!",
  ui_story_5063_50631101_48_dialog_content = "Pam! Soltem minha filha, seus brutos!!",
  ui_story_5063_50631101_49_dialog_content = "Isso realmente está acontecendo? O testamento que meu mestre escreveu... Foi aceito pelo tribunal?",
  ui_story_5063_50631101_50_dialog_content = "Por que você está prendendo esta família? De quem são as ordens que você está seguindo?",
  ui_story_5063_50631101_51_dialog_content = "Membros da casa Pyrrhus ignoraram avisos e estavam pesquisando os cristais vermelhos. O Senhor da Cidade e o Juiz Chefe emitiram ordens para a prisão de todos os membros da família.",
  ui_story_5063_50631101_52_dialog_content = "Estes são os julgamentos e mandados de prisão! Pessoas não envolvidas, saiam imediatamente, ou prenderemos todos vocês!",
  ui_story_5063_50631101_53_dialog_content = "E-Espere! Eu não faço parte dessa família!",
  ui_story_5063_50631101_54_dialog_content = "Se você está envolvido ou não, vamos investigar isso minuciosamente. Agora, siga em frente!",
  ui_story_5063_50631101_55_dialog_content = "Pam...",
  ui_story_5063_50631101_56_dialog_content = "Perdoe-me, Senhora Irridon... Eu pretendia convidá-la para jantar com minha família, mas parece que teremos que remarcar.",
  ui_story_5063_50631101_57_dialog_content = "Mantenha-se forte! Vou encontrar um jeito de te salvar!",
  ui_story_5063_50631101_58_dialog_content = "Você já fez tanto por mim, então por favor não se incomode mais por minha causa... Isso só pesaria ainda mais no meu coração.",
  ui_story_5063_50631101_59_dialog_content = "Até eu sei que pesquisar os cristais vermelhos é estritamente proibido. Embora meus pais e eu não tenhamos cometido nenhum crime...",
  ui_story_5063_50631101_60_dialog_content = "Quando um dos nossos é considerado culpado, toda a nossa família carrega o peso de seus pecados.",
  ui_story_5063_50631101_61_dialog_content = "Mas não se preocupe. Vou aproveitar esta oportunidade para mostrar ao Deus da Luz meu arrependimento e devoção, e continuar me esforçando para me tornar uma freira do Templo de Lumopolis!",
  ui_story_5063_50631101_62_dialog_content = "Caso esse dia chegue, tenho certeza de que você também será um juiz plenamente capacitado do Tribunal de Justiça.",
  ui_story_5063_50631101_63_dialog_content = "Eu... Eu darei o meu melhor! Me tornarei um juiz puro e justo algum dia!",
  ui_story_5063_50631101_64_dialog_content = "Mexa-se! Sem tempo para bate-papo!",
  ui_story_5063_50631101_65_dialog_content = "Até o próximo encontro, meu amigo!",
  ui_story_5063_50631101_66_dialog_content = "Adeus...",
  ui_story_5063_50631103_1_dialog_content = "É mais um dos vereditos do meu pai?",
  ui_story_5063_50631103_2_dialog_content = "Não... Este é um relatório de investigação particular escrito pelo meu próprio pai.",
  ui_story_5063_50631103_3_dialog_content = "\"Antes de falecer, o falecido barão descobriu que toda a sua família seria presa em breve.\"",
  ui_story_5063_50631103_4_dialog_content = "\"Com medo de que seu filho e neta fossem implicados, ele elaborou um último plano desesperado.\"",
  ui_story_5063_50631103_5_dialog_content = "\"Ao conceder seu título e propriedade ao seu servo mais próximo em seu testamento, o falecido barão acreditava que sua família seria poupada.\"",
  ui_story_5063_50631103_6_dialog_content = "O quê...? Como e quando meu pai descobriu detalhes tão chocantes?",
  ui_story_5063_50631103_7_dialog_content = "Mesmo que fosse para proteger sua família, o avô da Pam não tinha o direito de envolver seu servo inocente!",
  ui_story_5063_50631103_8_dialog_content = "<size=45>!!!</size>",
  ui_story_5063_50631103_9_dialog_content = "Então meu pai estava ciente das intenções do barão o tempo todo. Foi por isso que ele escolheu anular seu testamento?",
  ui_story_5063_50631103_10_dialog_content = "Como esperado... A decisão do Pai estava correta, afinal...",
  ui_story_5063_50631103_11_dialog_content = "O-O que eu fiz...?",
  ui_story_5063_50631201_1_dialog_content = "Procurei por todo o Pátio de Lumópolis, mas ainda não encontrei a mulher de preto. Será que ela fugiu para a Baixa Lumópolis?",
  ui_story_5063_50631201_2_dialog_content = "Nunca fiz muitas viagens à Baixa Lumópolis no passado... Até o clima é completamente diferente das partes superiores da cidade.",
  ui_story_5063_50631201_3_dialog_content = "Sinto inúmeros olhos me observando enquanto caminho pelas ruas... A presença de um Cavaleiro da Justiça é realmente tão fora do lugar aqui?",
  ui_story_5063_50631201_4_dialog_content = "O que você está fazendo aqui, Cavaleiro da Justiça?",
  ui_story_5063_50631201_5_dialog_content = "J-Juiz Chefe?!",
  ui_story_5063_50631201_6_dialog_content = "Eu... M-Mil desculpas, mas devido à minha própria inadequação, ainda não consegui capturar a mulher de preto.",
  ui_story_5063_50631201_7_dialog_content = "Mas durante minha busca, consegui resolver vários casos não relacionados para alguns dos moradores locais...",
  ui_story_5063_50631201_8_dialog_content = "A mulher de preto? Que mulher de preto?",
  ui_story_5063_50631201_9_dialog_content = "Hã? A pessoa que invadiu o Tribunal de Justiça e pediu que você limpasse o nome dela...",
  ui_story_5063_50631201_10_dialog_content = "Hmm... agora que você mencionou, eu me lembro vagamente de tal pessoa.",
  ui_story_5063_50631201_11_dialog_content = "Mas podemos deixar isso de lado por enquanto. Tenho uma tarefa mais importante para você.",
  ui_story_5063_50631201_12_dialog_content = "Recebemos informações sugerindo que Mirren Gautier pode estar envolvido em traição. Investigue se essa pista tem alguma verdade.",
  ui_story_5063_50631201_13_dialog_content = "A-Tem certeza de que deseja me deixar com uma tarefa tão importante?",
  ui_story_5063_50631201_14_dialog_content = "Er, eu quis dizer... Obrigado por confiar em mim, Juiz Chefe! Vou começar minha investigação sobre a suspeita de traição de Mirren Gautier imediatamente...",
  ui_story_5063_50631201_15_dialog_content = "Espere... Alguém planeja se rebelar contra a cidade?!",
  ui_story_5063_50631201_16_dialog_content = "Esta tarefa diz respeito à sobrevivência de Lumopolis, o que significa que deve ser realizada de forma impecável, sem margem para erros. Você entende?",
  ui_story_5063_50631201_17_dialog_content = "Sim, Juiz Chefe!",
  ui_story_5063_50631201_18_dialog_content = "Não permitirei que ninguém profane a cidade que jurei proteger!",
  ui_story_5063_50631201_19_dialog_content = "Também não vou permitir decepcioná-lo, Juiz Chefe...",
  ui_story_5063_50631201_20_dialog_content = "Proteção! Lealdade! Glória!",
  ui_story_5063_50631201_21_dialog_content = "De novo... De onde eles continuam vindo?!",
  ui_story_5063_50631201_22_dialog_content = "Por favor, recue para um local seguro, Juiz Chefe! Eu posso lidar com eles!",
  ui_story_5063_50631201_23_dialog_content = "Ataque!",
  ui_story_5063_50631302_1_dialog_content = "(A Juíza Chefe disse que não conseguia ver aqueles guardas estranhos...)",
  ui_story_5063_50631302_2_dialog_content = "(Será que só eu consigo vê-los?)",
  ui_story_5063_50631302_3_dialog_content = "Meus olhos me enganam... É você, Senhora Irridon?",
  ui_story_5063_50631302_4_dialog_content = "Pam?!",
  ui_story_5063_50631302_5_dialog_content = "Avante, Noite Branca! É mesmo você! Mas o que está fazendo na Lumópolis Inferior?",
  ui_story_5063_50631302_6_dialog_content = "Achei que não te veria novamente por muito mais tempo...",
  ui_story_5063_50631302_7_dialog_content = "Tenho um trabalho a fazer aqui embaixo. Você... tem passado bem?",
  ui_story_5063_50631302_8_dialog_content = "Sim! Como você pode ver, meu corpo e espírito estão em perfeita saúde!",
  ui_story_5063_50631302_9_dialog_content = "Ouvi dizer que sua família inteira foi privada de seus Luminatics...",
  ui_story_5063_50631302_10_dialog_content = "Isso... era de se esperar. Afinal, nossa família foi responsável por cometer um pecado imperdoável.",
  ui_story_5063_50631302_11_dialog_content = "Pela lei de Lumópolis, nossa punição é totalmente adequada.",
  ui_story_5063_50631302_12_dialog_content = "...D-De qualquer forma, vejo tudo isso como uma experiência totalmente nova! Afinal, eu nunca tinha ido à Baixa Lumópolis antes do nosso exílio!",
  ui_story_5063_50631302_13_dialog_content = "Enquanto nossa família permanecer unida, podemos sobreviver em qualquer lugar!",
  ui_story_5063_50631302_14_dialog_content = "Mas e a provação do Templo de Lumópolis...?",
  ui_story_5063_50631302_15_dialog_content = "Bem, é verdade que eu não tenho como voltar agora...",
  ui_story_5063_50631302_16_dialog_content = "Mas mesmo assim, minha fé se mantém firme. Rezo ao Deus da Luz todos os dias pela absolvição, assim como sempre fiz no passado.",
  ui_story_5063_50631302_17_dialog_content = "Enquanto eu perseverar, tenho certeza de que haverá um lugar para mim no Templo de Lumópolis no futuro!",
  ui_story_5063_50631302_18_dialog_content = "Seu puro otimismo me deixa sem palavras...",
  ui_story_5063_50631302_19_dialog_content = "Ao contrário de você, estou cheio de dúvidas e apreensão, tanto que não consigo nem mesmo completar as tarefas que estão diante de mim.",
  ui_story_5063_50631302_20_dialog_content = "Não há necessidade de se comparar aos outros, sabe? Cada pessoa é única e tem seus próprios problemas para resolver na vida.",
  ui_story_5063_50631302_21_dialog_content = "Em meus olhos, Senhora Irridon, você já é uma pessoa excepcional e trabalhadora. Tem certeza de que não está esperando demais de si mesma?",
  ui_story_5063_50631302_22_dialog_content = "Você... Acha mesmo isso?",
  ui_story_5063_50631302_23_dialog_content = "Nossa... Por que de repente sou eu quem está sendo confortado?",
  ui_story_5063_50631302_24_dialog_content = "...Mas chega disso. Se você ou sua família tiverem algum problema, você deve me contar imediatamente!",
  ui_story_5063_50631302_25_dialog_content = "Hahaha! Sua preocupação é muito apreciada, Senhora Irridon!",
  ui_story_5063_50631302_26_dialog_content = "Oh? Já é hora do almoço? Se você ainda não comeu, gostaria de se juntar a nós?",
  ui_story_5063_50631302_27_dialog_content = "Se não for muito incômodo, então sim...",
  ui_story_5063_50631302_28_dialog_content = "Afinal, esta é... A primeira vez que um amigo me convida para comer junto. Seria uma honra me juntar a você!",
  ui_story_5063_50631302_29_dialog_content = "A comida estará pronta em apenas alguns minutos!",
  ui_story_5063_50631302_30_dialog_content = "Desde que nos conhecemos, eu queria te convidar para jantar com minha família...",
  ui_story_5063_50631302_31_dialog_content = "Eu estava começando a pensar que nunca era para ser... Mas então o destino nos uniu novamente, aqui na Baixa Lumópolis!",
  ui_story_5063_50631302_32_dialog_content = "Sei que não é jantar e não há muitos pratos para escolher...",
  ui_story_5063_50631302_33_dialog_content = "Mas, através de estudo e prática, aprendi a fazer refeições decentes com os poucos ingredientes disponíveis para nós aqui!",
  ui_story_5063_50631302_34_dialog_content = "Sim, e você tem a mim para agradecer pelas habilidades culinárias que herdou, Pam! Hahahaha!",
  ui_story_5063_50631302_35_dialog_content = "Apenas agradeço por não ter herdado sua arrogância também, pai!",
  ui_story_5063_50631302_36_dialog_content = "P-Pam! Como você pode ridicularizar seu pobre pai na frente da Senhora Irridon?!",
  ui_story_5063_50631302_37_dialog_content = "Heehee, só estou brincando! Afinal, sua mãe faz isso com você o tempo todo, não é?",
  ui_story_5063_50631302_38_dialog_content = "Você deve perdoar minha filha por seu comportamento tolo, Senhora Irridon. Por favor, fique à vontade.",
  ui_story_5063_50631302_39_dialog_content = "Posso garantir que você não vai provar nada parecido com isso nos Jardins de Lumópolis! Hahahaha!",
  ui_story_5063_50631302_40_dialog_content = "Eu sei que não parece particularmente extravagante, mas...",
  ui_story_5063_50631302_41_dialog_content = "Mastigar...",
  ui_story_5063_50631302_42_dialog_content = "E aí? Isso agrada seu paladar?",
  ui_story_5063_50631302_43_dialog_content = "<size=45>!!!</size>",
  ui_story_5063_50631302_44_dialog_content = "...É tão delicioso.",
  ui_story_5063_50631302_45_dialog_content = "Na verdade, meu corpo está cheio de energia renovada depois de experimentá-lo!",
  ui_story_5063_50631302_46_dialog_content = "Eu nunca soube que uma tigela de sopa poderia me fazer sentir tão incrível...",
  ui_story_5063_50631302_47_dialog_content = "Você não adicionou uma poção de Lúmina nisso, adicionou Pam?",
  ui_story_5063_50631302_48_dialog_content = "E onde diabos eu encontraria dinheiro para um ingrediente tão caro, Senhora Irridon?",
  ui_story_5063_50631302_49_dialog_content = "Não, se for o caso... O que você está provando só pode ser descrito como <color=#FFB400>o amor de uma família</color>.",
  ui_story_5063_50631302_50_dialog_content = "\"O amor de uma família...\"",
  ui_story_5063_50631302_51_dialog_content = "Novamente, você deve perdoar minha filha, Senhora Irridon. Às vezes, a fala dela pode ser um pouco confusa.",
  ui_story_5063_50631302_52_dialog_content = "Pelo contrário, sou muito grato à Pam por compartilhar seus pensamentos comigo.",
  ui_story_5063_50631302_53_dialog_content = "Além disso, acredito que também devo pedir desculpas a você em relação ao testamento do seu pai...",
  ui_story_5063_50631302_54_dialog_content = "Não há necessidade, minha senhora. Está tudo no passado agora, e eu já aceitei isso há muito tempo.",
  ui_story_5063_50631302_55_dialog_content = "Quando chegamos à Baixa Lumópolis, não éramos diferentes dos plebeus que antes víamos com tanto desprezo. No início, achei que nossas vidas seriam repletas de miséria e sofrimento.",
  ui_story_5063_50631302_56_dialog_content = "Mas como plebeus, logo descobri que as pessoas ao nosso redor eram muito melhores em ajudar e cuidar umas das outras do que qualquer aristocrata que já conheci.",
  ui_story_5063_50631302_57_dialog_content = "Em Lumópolis, os nobres frequentemente precisam pisar nas pessoas abaixo deles para manter suas posições.",
  ui_story_5063_50631302_58_dialog_content = "A única maneira de evitar isso é empurrando os outros para baixo e pisoteando-os, em vez disso.",
  ui_story_5063_50631302_59_dialog_content = "No final do dia, qual seria o sentido de retornar a uma vida tão exploradora?",
  ui_story_5063_50631302_60_dialog_content = "Meu único arrependimento é que Pam perdeu a chance de entrar no Templo de Lumópolis...",
  ui_story_5063_50631302_61_dialog_content = "Mas como um ramo da família Pyrrhus, você nunca foi diretamente responsável por nenhum dos crimes deles.",
  ui_story_5063_50631302_62_dialog_content = "Não apenas isso, mas não consigo pensar em alguém mais digna de se tornar freira do que a Pam. Sua devoção e personalidade me mostram isso.",
  ui_story_5063_50631302_63_dialog_content = "Quando eu terminar minha tarefa atual, com certeza vou relatar isso à Juíza Chefe. Talvez ela permita que ela retorne ao Templo de Lumópolis!",
  ui_story_5063_50631303_1_dialog_content = "\"A família Pyrrhus, em conjunto com a família Gautier, utilizou Eclipsitas aprimorados para realizar uma rebelião violenta...\"",
  ui_story_5063_50631303_2_dialog_content = "\"Cada membro de suas respectivas famílias foi condenado à morte. Em caso de resistência adicional, eles serão executados no local.\"",
  ui_story_5063_50631303_3_dialog_content = "I-Isso é outro veredito do meu pai...?",
  ui_story_5063_50631303_4_dialog_content = "Mas isso é completamente contrário às descobertas da minha investigação!",
  ui_story_5063_50631303_5_dialog_content = "É verdade que ambas as famílias foram exiladas para a Baixa Lumópolis como resultado das pesquisas da família Pyrrhus sobre os cristais vermelhos...",
  ui_story_5063_50631303_6_dialog_content = "Mas agora, aqueles que estão conspirando com os Eclipsitas para perseguir a família Pyrrhus são nada menos que Mirren Gautier e seus parentes!",
  ui_story_5063_50631303_7_dialog_content = "Com certeza, meu pai não poderia ter perdido um detalhe tão importante...",
  ui_story_5063_50631303_8_dialog_content = "Então, por que ele faria um julgamento assim?",
  ui_story_5063_50631303_9_dialog_content = "Este caso afeta toda a Lumópolis e sua segurança... Será que estou realmente confiante o suficiente no meu próprio julgamento para anular o veredicto do meu pai?",
  ui_story_5063_50631303_10_dialog_content = "Poderia ser... Ele descobriu algo mais?",
  ui_story_5063_50631303_11_dialog_content = "De qualquer forma, não há motivo para continuar perseguindo uma família inocente por causa disso!",
  ui_story_5063_50631303_12_dialog_content = "Pai…",
  ui_story_5063_50631303_13_dialog_content = "Parece que a distância entre nós... só aumentou...",
  ui_story_5063_50631601_1_dialog_content = "...Isso conclui meu relatório de investigação.",
  ui_story_5063_50631601_2_dialog_content = "Bom, vou relatar imediatamente os resultados dessa investigação ao Juiz Supremo!",
  ui_story_5063_50631601_3_dialog_content = "Você tem minha gratidão!",
  ui_story_5063_50631601_4_dialog_content = "Agora, ainda tenho uma última coisa a fazer...",
  ui_story_5063_50631601_5_dialog_content = "Você tem progredido em sua missão, Senhora Irridon?",
  ui_story_5063_50631601_6_dialog_content = "Er... Sim. Na verdade, o assunto está praticamente concluído agora.",
  ui_story_5063_50631601_7_dialog_content = "Então... Você vai embora em breve?",
  ui_story_5063_50631601_8_dialog_content = "Por favor, não entenda mal! Eu simplesmente pensei que, se você não estivesse com pressa, poderia vir à nossa casa e jantar conosco.",
  ui_story_5063_50631601_9_dialog_content = "Mamãe e papai estão preparando um banquete neste exato momento!",
  ui_story_5063_50631601_10_dialog_content = "Ahhhh!",
  ui_story_5063_50631601_11_dialog_content = "<size=45>Expurgar os traidores! Expurgar os traidores! Expurgar os traidores!</size>",
  ui_story_5063_50631601_12_dialog_content = "Por que esses guardas estão prendendo todo mundo?!",
  ui_story_5063_50631601_13_dialog_content = "<size=45>Expurgar os traidores! Expurgar os traidores! Expurgar os traidores!</size>",
  ui_story_5063_50631601_14_dialog_content = "(Parece que o Juiz-Chefe já deu a ordem para prender a família Gautier... Mas o que isso tem a ver com a família Pyrrhus?)",
  ui_story_5063_50631601_15_dialog_content = "(Será que o Juiz Chefe acha que as duas famílias estão conspirando juntas?)",
  ui_story_5063_50631601_16_dialog_content = "(Mas isso significaria que a Pam é...)",
  ui_story_5063_50631601_17_dialog_content = "Huh? Pai!",
  ui_story_5063_50631601_18_dialog_content = "Pam...! Esqueça de mim!",
  ui_story_5063_50631601_19_dialog_content = "<size=45>Fuja, Pam! Corra o mais rápido que puder!!!</size>",
  ui_story_5063_50631601_20_dialog_content = "Por que estão prendendo meu pai, Senhora Irridon?!",
  ui_story_5063_50631601_21_dialog_content = "Nós não fizemos nada além de obedecer à lei desde que chegamos à Baixa Lumópolis, então por quê... Me diga, Senhora Irridon!",
  ui_story_5063_50631601_22_dialog_content = "Será que isso tem algo a ver com sua missão...?",
  ui_story_5063_50631601_23_dialog_content = "Não posso te contar sobre minha tarefa, Pam. Pelo menos não agora... Mas posso te garantir que não tem nada a ver com isso!",
  ui_story_5063_50631601_24_dialog_content = "Por enquanto, apenas ouça seu pai e corra!",
  ui_story_5063_50631601_25_dialog_content = "<size=45>Agora vá!</size>",
  ui_story_5063_50631601_26_dialog_content = "Um membro da família Pyrrhus conseguiu escapar por ali?",
  ui_story_5063_50631601_27_dialog_content = "Deixem suas suspeitas de lado, guardas; aquela garota não pertence à família Pyrrhus. Ela simplesmente entrou em pânico ao ver a cena e fugiu.",
  ui_story_5063_50631601_28_dialog_content = "Entendi. Vamos procurar novamente por lá!",
  ui_story_5063_50631601_29_dialog_content = "Pam...",
  ui_story_5063_50631601_30_dialog_content = "Heheh, então até mesmo o Cavaleiro da Justiça é capaz de contar mentiras, né?",
  ui_story_5063_50631601_31_dialog_content = "É você! Eu estive procurando por você há algum tempo... Que gentileza sua se entregar para mim!",
  ui_story_5063_50631601_32_dialog_content = "Você, um Cavaleiro da Justiça de Lumópolis, deixou um criminoso tão importante escapar por entre seus dedos...",
  ui_story_5063_50631601_33_dialog_content = "Que crime você acha que cometeu?",
  ui_story_5063_50631601_34_dialog_content = "Como um Cavaleiro da Justiça, defender as leis de Lumopolis não é minha única responsabilidade. Também tenho a obrigação de proteger as pessoas inocentes desta cidade!",
  ui_story_5063_50631601_35_dialog_content = "Deve haver algum tipo de mal-entendido! Por que mais o Juiz-Chefe prenderia toda a família Pyrrhus...?",
  ui_story_5063_50631601_36_dialog_content = "Vou explicar tudo a ela na primeira oportunidade que tiver e livrar a Pam e sua família de qualquer irregularidade!",
  ui_story_5063_50631601_37_dialog_content = "Ah? Se é esse o caso, por que você está me perseguindo tão implacavelmente?",
  ui_story_5063_50631601_38_dialog_content = "Porque você...",
  ui_story_5063_50631601_39_dialog_content = "Hum?",
  ui_story_5063_50631601_40_dialog_content = "Tu es...",
  ui_story_5063_50631601_41_dialog_content = "<size=45><color=#FFB400>Pam</color>?!</size>",
  ui_story_5063_50631601_42_dialog_content = "Faz séculos que alguém me chamou por aquele nome...",
  ui_story_5063_50631601_43_dialog_content = "Mas talvez você me conheça melhor por um dos nomes na sua lista dos mais procurados: <color=#FFB400>Paloma Pyrrhus</color>.",
  ui_story_5063_50631601_44_dialog_content = "Você esteve mentindo para mim todo esse tempo...?",
  ui_story_5063_50631601_45_dialog_content = "Oh? Heheh, parece que você esqueceu mesmo...",
  ui_story_5063_50631601_46_dialog_content = "Você está disposto a me contar o que aconteceu com você?",
  ui_story_5063_50631601_47_dialog_content = "Você é quem me pediu para explicar minha situação.",
  ui_story_5063_50631601_48_dialog_content = "Mas, justo quando eu estava prestes a fazer isso, \"Pam\" de repente se desprendeu do meu corpo.",
  ui_story_5063_50631601_49_dialog_content = "A pessoa que você conhece como Pam sou eu, mas ao mesmo tempo ela não sou eu...",
  ui_story_5063_50631601_50_dialog_content = "Neste exato momento, ela deve estar escondida em algum lugar e sentindo a mesma dor que eu senti há mais de uma década... Pobrezinha.",
  ui_story_5063_50631601_51_dialog_content = "Então, quando você forçou sua entrada no Tribunal de Justiça... Foi para denunciar esse ato de rebelião?",
  ui_story_5063_50631601_52_dialog_content = "Eu deveria ter percebido isso antes...",
  ui_story_5063_50631601_53_dialog_content = "Mas ainda há tempo! Vou apenas relatar minhas descobertas ao Juiz Chefe e inocentar a Pam... E você também!",
  ui_story_5063_50631601_54_dialog_content = "Vamos ter que esperar e ver, não é mesmo?",
  ui_story_5063_50631601_55_dialog_content = "Cavaleiro da Justiça!",
  ui_story_5063_50631601_56_dialog_content = "A fugitiva está bem diante dos seus olhos. Por que você ainda não a prendeu?",
  ui_story_5063_50631601_57_dialog_content = "Antes disso, gostaria de saber o que o levou a autorizar as prisões das famílias Gautier e Pyrrhus.",
  ui_story_5063_50631601_58_dialog_content = "Isso não é tudo graças à sua investigação?",
  ui_story_5063_50631601_59_dialog_content = "Mas minha investigação já provou que a maioria dos membros da família Pyrrhus são vítimas neste caso, não perpetradores!",
  ui_story_5063_50631601_60_dialog_content = "Ambas as famílias Gautier e Pyrrhus estavam envolvidas em experimentos proibidos. Não é verdade?",
  ui_story_5063_50631601_61_dialog_content = "Sim, mas eles já foram punidos por aquele crime. Além disso, você não pode responsabilizar todas as pessoas de suas famílias por isso.",
  ui_story_5063_50631601_62_dialog_content = "Cavaleiro da Justiça! Eu realmente preciso analisar cada um para ver quem se transformou em um monstro voluntariamente por traição e quem não fez isso?",
  ui_story_5063_50631601_63_dialog_content = "Para manter a segurança e estabilidade de Lumópolis, não podemos nos dar ao luxo de deixar qualquer risco potencial.",
  ui_story_5063_50631601_64_dialog_content = "E quanto às pessoas inocentes que não tiveram participação nesses experimentos?",
  ui_story_5063_50631601_65_dialog_content = "Eles não se tornaram monstros... Eles não fizeram nada! Então, por que eles devem levar a culpa e perder suas vidas por isso?",
  ui_story_5063_50631601_66_dialog_content = "Inocentes? Que piada! A família Pyrrhus era culpada desde o início. Quando o Tribunal de Justiça os condenou ao exílio em Lumópolis Inferior, já era uma misericórdia.",
  ui_story_5063_50631601_67_dialog_content = "Agora, eles até se envolveram neste caso de traição... Por que deveríamos pegar leve com um bando de criminosos em potencial de Lumopolis Inferior?",
  ui_story_5063_50631601_68_dialog_content = "Como você pode determinar se uma pessoa merece tratamento justo perante a lei com base apenas em seu status e residência?!",
  ui_story_5063_50631601_69_dialog_content = "Ainda acredito que seu julgamento está falho, Juiz Chefe——",
  ui_story_5063_50631601_70_dialog_content = "Este é um julgamento que seu pai também faria!",
  ui_story_5063_50631601_71_dialog_content = "Seu pai é um Juiz Chefe de Lumópolis muito respeitado. O quê, você está indo contra seu próprio pai agora?",
  ui_story_5063_50631601_72_dialog_content = "Eu...",
  ui_story_5063_50631601_73_dialog_content = "Hehehe.",
  ui_story_5063_50631601_74_dialog_content = "Então você ainda tem esperança em Lumopolis e no Hall of Justice, pelo que vejo?",
  ui_story_5063_50631601_75_dialog_content = "Não deixe que eles continuem te manipulando!",
  ui_story_5063_50631601_76_dialog_content = "O que você está fazendo?!",
  ui_story_5063_50631601_77_dialog_content = "Eu não vou tentar te machucar, mas é melhor ficar fora do caminho!",
  ui_story_5063_50631601_78_dialog_content = "É hora de eu erradicar a fonte do mal escondida atrás de você!",
  ui_story_5063_50631601_79_dialog_content = "Cavaleiro da Justiça! Derrube essa mulher louca agora!",
  ui_story_5063_50631601_80_dialog_content = "...",
  ui_story_5063_50631601_81_dialog_content = "Pare, Paloma!",
  ui_story_5063_50631601_82_dialog_content = "Heheh... Você realmente não é diferente deles.",
  ui_story_5063_50631601_83_dialog_content = "Não, Paloma... Eu simplesmente me recuso a ver você cometer um erro ainda maior!",
  ui_story_5063_50631601_84_dialog_content = "Você não são os únicos a decidir o que é certo ou errado. Não existe justiça em Lumópolis!",
  ui_story_5063_50631601_85_dialog_content = "Matar alguém também não trará a justiça que você busca!",
  ui_story_5063_50631601_86_dialog_content = "Se você não lidar com um problema em sua origem, ele nunca desaparecerá! Você poderia destruir toda a Lumópolis, e ainda assim não interromperia o ciclo de ódio e vingança!",
  ui_story_5063_50631601_87_dialog_content = "Com o tempo, alguém criaria um Tribunal de Justiça ainda mais arrogante e preconceituoso!",
  ui_story_5063_50631601_88_dialog_content = "Além disso, você realmente vai fazer isso? Você não ressente a nobreza por eliminar todos que estão em seu caminho?",
  ui_story_5063_50631601_89_dialog_content = "Está tentando se tornar como eles?!",
  ui_story_5063_50631601_90_dialog_content = "Eu não sou nada como eles!",
  ui_story_5063_50631601_91_dialog_content = "Então me diga, qual é a diferença entre suas ações agora e as deles?",
  ui_story_5063_50631601_92_dialog_content = "...",
  ui_story_5063_50631601_93_dialog_content = "Nesse caso... Você tem alguma ideia melhor?",
  ui_story_5063_50631601_94_dialog_content = "Momento perfeito!",
  ui_story_5063_50631601_95_dialog_content = "Desmembrar!",
  ui_story_5063_50631601_96_dialog_content = "Urgh! Droga... Eu deveria ter esperado um ataque furtivo...",
  ui_story_5063_50631601_97_dialog_content = "Que pena para você... Você me subestimou...",
  ui_story_5063_50631601_98_dialog_content = "*tosse* Cavaleiro da Justiça... prenda... essa mulher louca... *tosse*",
  ui_story_5063_50631601_99_dialog_content = "Estarei no Salão da Justiça... aguardando sua atualização...",
  ui_story_5063_50631601_100_dialog_content = "Hahaha! Isso mesmo, corra com seu rabo... Entre as pernas...",
  ui_story_5063_50631601_101_dialog_content = "Paloma! Você-Você tá bem?",
  ui_story_5063_50631601_102_dialog_content = "Heheh, então você finalmente me pegou. Agora você pode finalmente apresentar algo à sua preciosa Juíza Chefe que a deixará feliz.",
  ui_story_5063_50631601_103_dialog_content = "Você está perdendo muito sangue! Deixe-me ajudar!",
  ui_story_5063_50631601_104_dialog_content = "Hmph, você realmente não precisa continuar fingindo, sabe. Já passamos dessa fase.",
  ui_story_5063_50631601_105_dialog_content = "Ei! Você não me ouviu? Pare de perder tempo tentando tratar os meus ferimentos!",
  ui_story_5063_50631601_106_dialog_content = "Mas eu quero ajudar! O que mais você precisa que eu faça?",
  ui_story_5063_50631601_107_dialog_content = "Tch, não preciso da ajuda de ninguém, então desista. Tudo que preciso é de um veredicto justo... Acha que pode me dar isso?",
  ui_story_5063_50631601_108_dialog_content = "Eu... Claro que posso!",
  ui_story_5063_50631601_109_dialog_content = "Noite Branca nas alturas! Após uma extensa investigação, o Tribunal de Justiça conclui que o Major Pyrrhus e sua família não tinham intenções rebeldes. Além disso, eles não estavam envolvidos nos experimentos com Eclipsitas realizados pela família Gautier...",
  ui_story_5063_50631601_110_dialog_content = "Sendo assim, eu declaro que todos eles são... Inocentes!",
  ui_story_5063_50631601_111_dialog_content = "...Inocente, né?",
  ui_story_5063_50631601_112_dialog_content = "Heh, devo estar sonhando.",
  ui_story_5063_50631601_113_dialog_content = "Paloma? P-Para onde você está indo?",
  ui_story_5063_50631601_114_dialog_content = "Se eu realmente estou sonhando, então talvez seja hora de finalmente acordar.",
  ui_story_5063_50631601_115_dialog_content = "Como por você...",
  ui_story_5063_50631601_116_dialog_content = "Eu me pergunto se você fará o mesmo?",
  ui_story_5063_50631601_117_dialog_content = "Sério... Por que você quis se tornar um Cavaleiro da Justiça?",
  ui_story_5063_50631701_1_dialog_content = "Que lugar é esse? E... Pra onde estou indo?",
  ui_story_5063_50631701_2_dialog_content = "O Tribunal de Justiça?",
  ui_story_5063_50631701_3_dialog_content = "Sério... Por que você quis se tornar um Cavaleiro da Justiça?",
  ui_story_5063_50631701_4_dialog_content = "Não consigo nem lembrar o motivo pelo qual eu queria trabalhar no Tribunal de Justiça em primeiro lugar...",
  ui_story_5063_50631701_5_dialog_content = "Eu falhei em todas as tarefas que me foram dadas pelo Juiz Chefe.",
  ui_story_5063_50631701_6_dialog_content = "E cada veredito que eu dei é o completo oposto do que meu pai decidiu.",
  ui_story_5063_50631701_7_dialog_content = "Eu digo que quero mudar Lumópolis para melhor, mas... O que eu posso realmente realizar sozinho?",
  ui_story_5063_50631701_8_dialog_content = "<color=#e8d9bb>Zumbido...</color>",
  ui_story_5063_50631701_9_dialog_content = "Huh? O que foi isso?",
  ui_story_5063_50631701_10_dialog_content = "<color=#e8d9bb>Zumbido...</color>",
  ui_story_5063_50631701_11_dialog_content = "Por que minha lupa voou do meu bolso? Espere, há algo estranho na lente...",
  ui_story_5063_50631701_12_dialog_content = "Quê? T-Tem uma figura na lente!",
  ui_story_5063_50631701_13_dialog_content = "Espere, aquela figura... É a Juíza Chefe?",
  ui_story_5063_50631701_14_dialog_content = "Mas algo no rosto do Juiz Chefe está diferente. Parece... Meio dourado?",
  ui_story_5063_50631701_15_dialog_content = "Eh... Você... Você parece...",
  ui_story_5063_50631701_16_dialog_content = "É assim que você está agora!",
  ui_story_5063_50631701_17_dialog_content = "Quem é você...?",
  ui_story_5063_50631701_18_dialog_content = "Sou seu amigo, PlayerName!",
  ui_story_5063_50631701_19_dialog_content = "Mas isso não importa. O que importa é... você precisa lembrar quem você é!",
  ui_story_5063_50631701_20_dialog_content = "Eu... Eu sou eu. Irridon Novek, um Cavaleiro da Justiça de Lumópolis.",
  ui_story_5063_50631701_21_dialog_content = "Olhe neste espelho aqui! Ele mostra sua aparência!",
  ui_story_5063_50631701_22_dialog_content = "É... meu reflexo? Você deve estar brincando! Por que eu me pareceria exatamente com o Juiz Chefe?",
  ui_story_5063_50631701_23_dialog_content = "Porque você é realmente o Juiz Chefe!",
  ui_story_5063_50631701_24_dialog_content = "Eu sou a verdadeira Juíza Chefe? Então quem era aquela outra mulher de antes?",
  ui_story_5063_50631701_25_dialog_content = "Ela... também é você, mas apenas uma parte de você. Ela é a versão idealizada de si mesma que você aspira ser no mundo real...",
  ui_story_5063_50631701_26_dialog_content = "Mas ela não é realmente você! Porque você misturou muitas ideias de outras pessoas às suas próprias expectativas.",
  ui_story_5063_50631701_27_dialog_content = "Recupere seu verdadeiro eu!",
  ui_story_5063_50631701_28_dialog_content = "<size=45>Acorda agora!</size>",
  ui_story_5063_50631701_29_dialog_content = "...",
  ui_story_5063_50631701_30_dialog_content = "Por que você está me dizendo para \"acordar\"?",
  ui_story_5063_50631701_31_dialog_content = "Se eu realmente estou sonhando, então talvez seja hora de finalmente acordar.",
  ui_story_5063_50631701_32_dialog_content = "Como por você...",
  ui_story_5063_50631701_33_dialog_content = "Eu me pergunto se você fará o mesmo?",
  ui_story_5063_50631701_34_dialog_content = "Agora que penso nisso, tudo que eu vivenciei... Aquelas pessoas e seus casos... Algo realmente parecia um pouco estranho neles.",
  ui_story_5063_50631701_35_dialog_content = "Mas se eu realmente estou sonhando, como devo acordar?",
  ui_story_5063_50631701_36_dialog_content = "...Eu preciso encontrá-la. A outra eu.",
  ui_story_5063_50631801_1_dialog_content = "<color=#e8d9bb>Crec...</color>",
  ui_story_5063_50631801_2_dialog_content = "Você? Como conseguiu entrar aqui?",
  ui_story_5063_50631801_3_dialog_content = "O caso envolvendo o criminoso conhecido como Paloma foi resolvido. Diga-me, Juiz Supremo, você ficou satisfeito com o meu desempenho?",
  ui_story_5063_50631801_4_dialog_content = "Você tem sido muito indeciso. Se não fosse pela minha intervenção, você teria cometido um erro imperdoável.",
  ui_story_5063_50631801_5_dialog_content = "Se você tivesse obedecido às minhas ordens desde o início, as coisas teriam sido muito mais tranquilas.",
  ui_story_5063_50631801_6_dialog_content = "\"Mais suave\"? Você quer dizer me substituir, certo?",
  ui_story_5063_50631801_7_dialog_content = "Então você finalmente está começando a se lembrar...",
  ui_story_5063_50631801_8_dialog_content = "Entendi... Me substituir era o seu plano o tempo todo, não era?",
  ui_story_5063_50631801_9_dialog_content = "Infelizmente, eu não vou deixar isso acontecer, agora ou nunca!",
  ui_story_5063_50631801_10_dialog_content = "É inútil resistir ainda mais. Eu sou a filha perfeita que o pai sempre quis, não você.",
  ui_story_5063_50631801_11_dialog_content = "Apenas eu sou digno de ser o verdadeiro Juiz Chefe de Lumopolis!",
  ui_story_5063_50631801_12_dialog_content = "Você, por outro lado, só conseguiu ajudar e apoiar o mal! O sacrifício do pai é desperdiçado em alguém como você!",
  ui_story_5063_50631801_13_dialog_content = "É realmente assim? Obrigado... Acho que entendo meu pai um pouco melhor agora.",
  ui_story_5063_50631801_14_dialog_content = "Percebo agora que sempre estive ansioso para reexaminar os casos antigos do meu pai, para corrigir os erros dele e também os do Tribunal de Justiça...",
  ui_story_5063_50631801_15_dialog_content = "Mas o que eu mais desejo julgar... Não é o julgamento de vingança de Paloma.",
  ui_story_5063_50631801_16_dialog_content = "Mas sim as tradições arrogantes e preconceituosas de Lumópolis!",
  ui_story_5063_50631801_17_dialog_content = "Você está se ouvindo agora? Como pode afirmar que os veredictos do pai estavam errados?!",
  ui_story_5063_50631801_18_dialog_content = "Meu pai emitiu muitos julgamentos razoáveis em seu tempo, mas até ele cometeu erros. Esses erros levaram a veredictos injustos, que por sua vez levaram à morte de pessoas inocentes!",
  ui_story_5063_50631801_19_dialog_content = "Ele deveria ter sido responsabilizado por seus erros em um tribunal, mas sua morte pôs fim a qualquer investigação.",
  ui_story_5063_50631801_20_dialog_content = "Mas agora, eu finalmente sei o que impediu meu pai de tomar decisões melhores.",
  ui_story_5063_50631801_21_dialog_content = "Uma doença corria em suas veias, uma que assolou toda Lumópolis ao longo de sua longa história...",
  ui_story_5063_50631801_22_dialog_content = "Uma doença que se esconde no fundo do seu subconsciente, assim como no meu!",
  ui_story_5063_50631801_23_dialog_content = "É orgulho! O orgulho está no cerne da corrupção de Lumopolis, e ao julgá-lo, vou purificá-lo da minha própria alma!",
  ui_story_5063_50631801_24_dialog_content = "Você está apenas desafiando seu pai por ressentimento! Você ainda tem mais medo dele do que qualquer coisa!",
  ui_story_5063_50631801_25_dialog_content = "Admito que no passado eu tinha muito medo de enfrentá-lo.",
  ui_story_5063_50631801_26_dialog_content = "Ele pode não ter sido um bom pai... Mas eu sei que ele fez o melhor por mim.",
  ui_story_5063_50631801_27_dialog_content = "É por isso que eu nunca posso perdoar as tradições que o aprisionaram durante toda a sua vida!",
  ui_story_5063_50631801_28_dialog_content = "Se não fosse por eles, poderíamos ter sido mais como a Pam e o pai dela...",
  ui_story_5063_50631801_29_dialog_content = "Você perdeu a cabeça? Está realmente com inveja daqueles criminosos?!",
  ui_story_5063_50631801_30_dialog_content = "Você ainda se lembra por que queria se tornar Juiz Chefe?",
  ui_story_5063_50631801_31_dialog_content = "Para suceder meu pai e herdar seu legado, é claro!",
  ui_story_5063_50631801_32_dialog_content = "Minha razão é diferente. Me tornei Juiz-Chefe para proteger Lumopolis e seu povo...",
  ui_story_5063_50631801_33_dialog_content = "É por isso que eu nunca vou deixar você fazer do seu jeito!",
  ui_story_5063_50631801_34_dialog_content = "Agora vá embora, para que esta cidade finalmente se livre de seu orgulho malicioso!",
  ui_story_5063_50631802_1_dialog_content = "Não——",
  ui_story_5063_50631802_2_dialog_content = "Eu sou a filha ideal do meu pai, não você! Como eu poderia perder para você?!",
  ui_story_5063_50631802_3_dialog_content = "Porque sua visão de uma \"filha ideal\" foi criada quando eu ainda não entendia meu pai.",
  ui_story_5063_50631802_4_dialog_content = "Ao ser dura e impiedosa com os outros e comigo mesma, e ao julgar casos estritamente de acordo com a lei, pensei que poderia me tornar a filha que meu pai sempre quis.",
  ui_story_5063_50631802_5_dialog_content = "Mas eu estava errado. Depois de analisar os casos antigos do meu pai, descobri que, apesar de sua postura fria e distante...",
  ui_story_5063_50631802_6_dialog_content = "O pai se esforçou para reunir o máximo de provas possível antes de ir ao julgamento, para que pudesse entregar os veredictos mais justos possíveis.",
  ui_story_5063_50631802_7_dialog_content = "No entanto, sua ideia de \"justiça\" ainda estava manchada pela arrogância de tradições ultrapassadas.",
  ui_story_5063_50631802_8_dialog_content = "Isso explicaria por que todos dizem que o pai foi o melhor Juiz Chefe da história de Lumopolis e que eu nunca serei tão grandioso quanto ele.",
  ui_story_5063_50631802_9_dialog_content = "...Eu nunca entendi verdadeiramente ele ou sua maneira de pensar.",
  ui_story_5063_50631802_10_dialog_content = "Mas como juízes, desde que continuemos a dar o nosso melhor, o estado de direito eventualmente retornará a um equilíbrio.",
  ui_story_5063_50631802_11_dialog_content = "Meu pai me deu duas oportunidades de viver até agora. Embora seu sacrifício possa não ser suficiente para restaurar o equilíbrio entre nós...",
  ui_story_5063_50631802_12_dialog_content = "Estou disposto a aceitar isso.",
  ui_story_5063_50631802_13_dialog_content = "Continuarei seguindo os passos do meu pai, corrigindo seus erros e me esforçando para me tornar um juiz-chefe muito maior do que ele já foi...",
  ui_story_5063_50631802_14_dialog_content = "Com minha vida, equilibrarei as balanças da justiça!",
  ui_story_5063_50631802_15_dialog_content = "...",
  ui_story_5063_50631802_16_dialog_content = "Acredito que finalmente é hora de acordar.",
  ui_story_5063_50631802_17_dialog_content = "Avante, Noite Branca! Eu declaro aqui e agora——",
  ui_story_5063_50631802_18_dialog_content = "<size=45>O tribunal está suspenso!</size>"
}
return config
